// a mesma lista que está no cabeçalho deste arquivo: cada consulta com os parâmetros e um exemplo; cada escrita com as ações,
// os campos de cada uma e um exemplo
$saida = [
    "sem_parametros" => t('api.php devolve tudo o que está guardado na coleção do pedido, sem filtro: arvore, campos, lancamento_tipos, formulas, avisos, relogios (com os valores dos campos, o resultado de cada fórmula, os avisos, os lançamentos, a previsão e a linha do tempo inteira com o resumo), modos, plano (inteiro), config (inteira, da coleção), eventos (com os disparos), destinos, agendas, agendas_desejadas, criterios (com a nota de cada relógio), cron (todas as execuções guardadas), usuarios (os logins; o master vê todos), migracoes e motor, e as categorias dos documentos (documento_categorias). A senha dos usuários não existe no sistema: sai o hash dela (veja senhas). Os arquivos dos documentos não vêm (só os dados de cada um, em relogios[].documentos): eles saem pelo recurso=documento. Para pegar só uma parte, ou filtrar, ordenar e paginar: veja filtros.'),
    "autenticacao" => t('em todo pedido: o login do site (HTTP Basic: o usuário e a senha de uma conta), um token pessoal (Minha conta, Tokens de API: vale como o login do dono dele, com as coleções dele) ou o token do servidor (o API_TOKEN do config.php, com pelo menos 10 caracteres: vale como o master mais antigo), no cabeçalho X-Api-Token ou no parâmetro token. Sem nada: 401. A conta bloqueada pelo master, ou a de demonstração que venceu, não entra. Ex.: curl -u lucas:senha http://servidor/relojoeiro/api.php?recurso=hoje; curl -H "X-Api-Token: segredo" http://servidor/relojoeiro/api.php?recurso=hoje'),
    "colecoes" => t('cada pedido vale numa coleção: a do parâmetro colecao=<id>, senão a do cookie colecao (o seletor do menu das páginas), senão a primeira que o usuário vê (a dele). Uma coleção que ele não vê: 404, como se não existisse. Tudo o que se lê e se grava (os relógios, o plano, a configuração, os destinos, as agendas...) é dessa coleção; a árvore de grupos e o cadastro dela (campos, tipos, fórmulas, avisos, categorias, critérios dos grupos) são da árvore que a coleção usa, e valem em todas as coleções que usam a mesma árvore. Sem coleção nenhuma (a conta que só pediu acesso), só a conta responde (409 com sem_colecao nos outros recursos). O master vê todas as coleções; com como=<login> (ou o cookie como, da faixa Vendo como das páginas), ele vê e grava como aquele usuário'),
    "exclusoes" => t('toda exclusão é em dois passos: sem confirmar=1, a API não apaga nada e responde 409 com confirmar: true e impacto (o que sai junto, seguindo o banco em cascata, no banco inteiro: itens, desfeitos, colecoes, relogios, arquivos, bytes e o texto pronto); com confirmar=1, apaga. Os scripts mandam confirmar=1 de uma vez. Os arquivos dos documentos saem do disco na hora (os do relógio, da coleção, da árvore ou da conta que saiu)'),
    "mudancas" => t('toda gravação do recurso=rodizio que mexe no plano (todas menos acao=modo, que só marca o modo) responde também mudancas: o que mudou do plano de hoje em diante em relação ao de antes. mudaram: quantos dias mudaram; iguais: quantos ficaram com o mesmo relógio (o motivo pode ter mudado); texto: o resumo pronto ("3 dias mudaram; 11 ficaram com o mesmo relógio."); dias[]: cada dia que mudou, na ordem, com data, dia_semana_curto, antes e depois (relogio, livre ou vazio: sem plano), antes_relogio_id, antes_relogio, depois_relogio_id, depois_relogio, antes_texto e depois_texto (o nome, "livre" ou "sem plano"), motivo (o do novo; null num dia livre ou sem plano) e texto ("qua 22/10: Orient → Citizen")'),
    "trocar_hoje" => t('o relógio de hoje não se troca no próprio dia, a não ser que a Configuração deixe (config trocar_hoje=1; o padrão é 0): desligado, o recurso=rodizio recusa usando, trocar_dia com a data de hoje, resortear_hoje, sem_relogio, apagar_tudo com hoje=1, periodo começando hoje e manual que mude o dia de hoje (o Decida por mim e o relógio que hoje já tem passam), e o resortear vale a partir de amanhã mesmo com o dia ainda por começar. As marcações do pulso (recurso=lancamento) continuam livres, e o hoje, o plano, a ficha, o rodizio_manual e o config dizem trocar_hoje para as telas'),
