        "calcular" => ["descricao" => t('calcula uma fórmula sem gravar, em cada relógio (ou nos pedidos), com as partes da conta (o testar da página Cadastros); fórmula com erro de escrita: 400 com os erros'),
            "parametros" => ["expressao" => t('a fórmula'), "relogio" => t('um id ou vários separados por vírgula (vazio: todos)')],
            "exemplo" => t('curl -u lucas:senha -G "http://servidor/relojoeiro/api.php" --data-urlencode recurso=calcular --data-urlencode "expressao=energia * 2" -d relogio=10,12')],
        "avisos" => ["descricao" => t('os avisos de todos os relógios da coleção agora (os desejados, vendidos e arquivados não têm aviso), do mais urgente ao mais distante, com a data prevista, quanto falta, o estado (atrasado, em_breve, ok) e o texto'),
            "parametros" => [],
            "exemplo" => t('curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=avisos"')],
        "criterios" => ["descricao" => t('os conjuntos de critérios por lugar (parâmetros, subparâmetros, faixas), as variáveis que podem medir (com o limite), os lugares (quem tem critérios próprios e de quem herda), os modos e a nota de cada relógio com a conta'),
            "parametros" => [],
            "exemplo" => t('curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=criterios"')],
        "historico" => ["descricao" => t('a linha do tempo: trechos contínuos por estado (rodizio, pulso: em uso fora do plano, cada tipo de sessão, repouso) e as marcações, com o resumo do tempo em cada estado e os lançamentos crus do período'),
            "parametros" => ["relogio" => t('um id ou vários (relogio_id também vale; vazio: todos)'), "de, ate" => t('data ou data e hora; entra a linha que cruza o período'), "estado" => t('rodizio, pulso, winder, sol, repouso, marca... (um ou vários; linha_estado também vale)'), "limite" => t('por página (padrão 100, máximo 1000)'), "pagina" => t('a página'), "ordem" => t('desc (padrão, mais recente primeiro) ou asc; dois no mesmo instante saem pela ordem em que foram lançados (o id)')],
            "exemplo" => t('curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=historico&relogio=3&de=2026-09-01&estado=marca"')],
        "previsao" => ["descricao" => t('a previsão da energia dos relógios com leitura (o smartwatch): quanto dura usando, quando chega ao limite parado, com quanto entra no próximo rodízio e quanto precisa, e a confiança da conta'),
            "parametros" => ["relogio" => t('um id ou vários (vazio: todos)')],
            "exemplo" => t('curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=previsao&relogio=10"')],
        "plano" => ["descricao" => t('o plano gravado (a escala de dois anos sai inteira), o dia a dia da página Plano uma página por vez (dia_a_dia, com os dias livres no meio), com o modo ativo, o fim da escala e o último dia gravado; cada dia com o relógio, o bloco, a origem (sorteio ou manual) e o lembrete; os dias livres do período (sem relógio e sem sorteio, para escolher à mão); e o resumo do período (de hoje em diante), como a página Plano mostra: quantos dias cada relógio tem, a porcentagem, o próximo dia, quantos à mão e os relógios sem nenhum dia'),
            "parametros" => ["de, ate" => t('datas AAAA-MM-DD (vazio: o plano inteiro)'), "pagina" => t('a página do dia_a_dia (padrão 1)'), "por_pagina" => t('quantos dias por página no dia_a_dia (sem ele: o Mostrar até da Configuração, padrão 31)'), "relogio" => t('o id: o dia_a_dia só com os dias desse relógio'), "dias" => t('N: os próximos N dias, de hoje em diante (no lugar de de e ate); todos: de hoje até o fim do plano')],
            "exemplo" => t('curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=plano&de=2026-10-01&ate=2026-10-31"')],
        "desejos" => ["descricao" => t('a lista de desejos (a página Desejos): os relógios desejados, a prioridade mais alta primeiro, cada um com a marca, a referência, o preço-alvo, a prioridade e o link; a soma dos preços-alvo; e os que estão fora da coleção (emprestados, vendidos, arquivados). Pôr na coleção (o Comprei): recurso=relogio, acao=salvar, posse=colecao'),
            "parametros" => [],
            "exemplo" => t('curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=desejos"')],
        "estatisticas" => ["descricao" => t('o uso da coleção num período (a página Estatísticas): o resumo (dias com relógio, horas no pulso, relógios usados, o mais e o menos usado, o valor da coleção, o custo por uso médio), cada relógio (dias de uso, horas, a parte de cada um, o custo por uso, dias sem uso, a tendência), o uso por dia da semana e por mês, e a distribuição da coleção (por grupo, marca, ano da compra, situação e cada campo de lista); as porcentagens e as alturas das barras (0 a 100, comparadas com a maior) vêm prontas. Contam as sessões no pulso (partidas na meia-noite) e as marcações antigas no pulso (o dia, sem horas)'),
            "parametros" => ["de, ate" => t('datas AAAA-MM-DD (padrão: os últimos 90 dias, até hoje; ate depois de hoje vira hoje; até 3661 dias); de=tudo: desde o primeiro uso; inválidas: 400 com erro')],
            "exemplo" => t('curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=estatisticas&de=2026-01-01&ate=2026-06-30"')],
        "precisao" => ["descricao" => t('a precisão (a marcha) dos relógios, pelas leituras do desvio da hora e pelos acertos (os tipos de lançamento que medem a marcha): de um relógio, os pontos, os intervalos entre eles com a marcha de cada um (em segundos por dia: + adianta, − atrasa), a marcha do relógio (a média pesada pelo tempo de cada intervalo), quanto as marchas variam, a última, o desvio estimado agora, a marcha em cada posição e a marcha esperada (os campos marcha_min e marcha_max); sem relogio, um resumo de cada relógio da coleção que tem o tipo do desvio'),
            "parametros" => ["relogio" => t('o id do relógio (sem: o resumo de todos); um que não existe: 404')],
            "exemplo" => t('curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=precisao&relogio=4"')],
        "calibres" => ["descricao" => t('os calibres (o movimento: NH35, ST2130, B620...), um cadastro da árvore como os campos: cada um com o fabricante, o link do manual técnico, a observação (as recomendações), os valores dos campos do cadastro que ele define e os relógios da coleção que apontam para ele; e os campos que um calibre pode definir. O relógio com um calibre usa o valor dele mesmo, senão o do calibre, senão o padrão do campo'),
            "parametros" => [],
            "exemplo" => t('curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=calibres"')],
        "unidades" => ["descricao" => t('as unidades da árvore (Cadastros › Unidades), um cadastro como os campos: o símbolo (o que vai depois do número; o que o campo, o tipo de lançamento e a fórmula guardam), o nome, a base (a unidade da mesma grandeza em que esta se converte), o fator e o zero (na base = (valor - zero) × fator), a unidade em que o valor também aparece e quantos campos, tipos e fórmulas usam cada uma; na ordem das grandezas (cada base seguida das que se convertem nela). A função CONVERTER das fórmulas converte entre duas da mesma base'),
            "parametros" => [],
            "exemplo" => t('curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=unidades"')],
        "totais" => ["descricao" => t('os totais calculados nos relógios mostrados: os do rodapé da tabela dos relógios da página Hoje (embaixo de cada coluna) e os da página de totais (os quadros), na ordem do cadastro (a aba Totais dos Cadastros). Cada total é uma expressão do motor de fórmulas sobre o conjunto de relógios (CONTA, SOMA, MEDIA, AGRUPADO, FAIXAS... em funcoes; dentro delas, os campos, as fórmulas e as variáveis da tabela, em variaveis) e vem com o resultado pronto: um número, uma tabelinha com a linha de total ou um relógio com o valor, já no formato dele'),
            "parametros" => ["relogios" => t('os ids, separados por vírgula (os que o filtro da tabela deixa à mostra); sem: todos os da tabela (na coleção e emprestados); 0: nenhum'),
                "parte" => t('rodape (só os do rodapé), pagina (só os da página de totais) ou teste (nenhum: só o teste); sem: todos (o cadastro, com as colunas, os formatos, as funções e as variáveis)'),
                "expressao, formato" => t('testa uma expressão de total sem gravar (o Testar do cadastro), no formato pedido (padrão numero): o resultado vem em teste')],
            "exemplo" => t('curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=totais&parte=rodape&relogios=3,7,12"')],
        "hora_certa" => ["descricao" => t('a hora do servidor para acertar os relógios (a página Hora certa): a local no fuso do pedido (o do usuário, o da coleção ou o do sistema), a UTC (Zulu), a letra militar do fuso e o grupo data-hora, o calendário (dia do ano, semana ISO, trimestre, dia juliano) e a fase da lua (pelo ciclo médio, aproximada), como acertar e o relógio escolhido na Configuração (analógico, digital, anadigi ou ambos); agora_ms, em milissegundos, para a tela acertar o relógio dela'),
            "parametros" => [],
            "exemplo" => t('curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=hora_certa"')],
        "acessorios" => ["descricao" => t('os acessórios (a página Acessórios): pulseiras, caixas, estojos, ferramentas, carregadores, peças e outros, cada um com o tipo, o relógio de que ele é (ou solto), a observação, os campos dele (a largura, o material da pulseira) e os relógios em que ele serve, pelo tipo e pelo nome; os campos dos acessórios, os tipos, quantos de cada tipo, quantos soltos e os relógios (o menu). Gravar: escrita acessorios'),
            "parametros" => ["relogio" => t('o id: só os acessórios desse relógio; 0: só os soltos (sem ele: todos)')],
            "exemplo" => t('curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=acessorios&relogio=3"')],
        "winders" => ["descricao" => t('os winders da coleção (a página Winders), pelo nome: os dados de cada um (os campos do winder, Cadastros › Campos, para o winder: a marca, o modelo, o link do manual, os limites da almofada...), a observação, quantos documentos ele tem e as posições, na ordem, cada uma com o programa (o da página Programas, com as voltas por dia e em cada sentido), se está ligada, o relógio que está nela agora (com a carga, o que cada hora ali dá, pela fórmula winder_ganho, e quando enche, pela winder_falta), o lugar fixo (de quem é a posição e se ele está fora dela) e os avisos de limite da almofada; os campos do winder e da posição (os formulários), os relógios que podem ir para um winder (os que têm um tipo de lançamento marcado como winder), com a posição em que cada um está, e os programas para escolher. Gravar: escrita winders e winder_posicoes; pôr e tirar: escrita winder_posicoes (relogio_id) ou lancamento (iniciar, que devolve ao lugar dele, e encerrar)'),
            "exemplo" => t('curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=winders"')],
        "programas" => ["descricao" => t('os programas dos winders (a página Programas), pelo nome: cada um com o tipo de cadastro (por voltas ou por tempo), a velocidade do berço (contada) ou as voltas por dia do manual (de onde a velocidade sai), se funciona o dia todo ou em blocos (liga tantas horas e para tantas), a sequência dos movimentos, o cálculo (cada passo com as voltas e o tempo, o ciclo, quantas vezes por dia, o tempo girando, as voltas por dia e em cada sentido, os erros e os avisos) e as posições que o usam; os movimentos (a página Movimentos: cada giro, horário ou anti-horário, em voltas ou em tempo, e cada parada, com os programas que o usam), os tipos de movimento e os tipos de cadastro. Com previa=1, o cálculo de um programa sem gravar nada (o que a tela mostra enquanto a pessoa muda). Gravar: escrita movimentos e programas'),
            "parametros" => ["previa" => t('1: só o cálculo (calculo e sequencia) do programa dos outros parâmetros, os campos do programas salvar (medida, velocidade, tpd_manual, funciona, liga_horas, para_horas, sequencia); com id, o que não vier é o do programa gravado')],
            "exemplo" => t('curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=programas&previa=1&medida=tempo&tpd_manual=650&sequencia=3,1,4,1"')],
        "servicos" => ["descricao" => t('os serviços e diagnósticos (o quadro Serviços e diagnósticos do relógio): cada intervenção com a data, o tipo, a oficina, o que foi feito, a mão de obra, as peças e o custo de cada uma, o custo (a mão de obra mais as peças), o teste de estanqueidade, a marcha antes e depois (a informada pelo profissional e a medida pelo sistema nas leituras do desvio da hora), a garantia, a observação e os documentos, do mais novo para o mais velho; os tipos; e, com o relógio, o resumo (a resistência à água declarada no cadastro, separada da estanqueidade comprovada no último teste, quantos, o custo somado e o último) e os documentos dele que um serviço pode citar. Gravar: escrita servicos'),
            "parametros" => ["relogio" => t('o id: só os serviços desse relógio, com o resumo (sem ele: os de todos)')],
            "exemplo" => t('curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=servicos&relogio=3"')],
        "manutencao" => ["descricao" => t('a manutenção (a página Manutenção): as abertas (os relógios na oficina agora: a situação, desde quando, a previsão e se está atrasada, o orçamento, o aviso da situação), as manutenções (as do período e dos filtros, da mais nova para a mais velha, cada uma com a história, o que foi junto, os documentos e os serviços que a volta registrou), as oficinas com os contatos, o resumo (quantas abertas e atrasadas, por oficina, o gasto), as listas da manutenção, os relógios que podem ir (os da coleção, com a manutenção aberta de cada um) e os acessórios. Gravar: escrita manutencao'),
            "parametros" => ["relogio" => t('o id: só as manutenções desse relógio'), "oficina" => t('o id: só as dessa oficina'),
                "de" => t('o começo do período (AAAA-MM-DD): as que estiveram abertas em algum dia dele'), "ate" => t('o fim do período (AAAA-MM-DD)')],
            "exemplo" => t('curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=manutencao&oficina=2&de=2026-01-01"')],
        "oficinas" => ["descricao" => t('as oficinas da coleção (Manutenção › Oficinas), por nome, com o endereço, o horário, os contatos (o principal primeiro, cada um com o link que abre), quantas manutenções e o gasto; os tipos de oficina e de contato. Gravar: escrita oficinas'),
            "parametros" => [], "exemplo" => t('curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=oficinas"')],
        "listas" => ["descricao" => t('as listas que são cadastro, na árvore da coleção: a situação do relógio na coleção, os tipos de acessório, os jeitos de carregar e as observações da reserva (Cadastros › Listas), as situações da manutenção, os tipos de serviço, os resultados da estanqueidade e os tipos de oficina e de contato (Manutenção › Listas). Cada lista com o que o texto do item quer dizer, se tem cor, os identificadores reservados, o que cada item pode fazer e os itens, com quantas vezes cada um está em uso. Gravar: escrita listas'),
            "parametros" => ["pagina" => t('cadastros ou manutencao: só as listas dessa página'), "lista" => t('o identificador de uma lista: só ela')],
            "exemplo" => t('curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=listas&pagina=manutencao"')],
        "timegrapher" => ["descricao" => t('as medições do timegrapher (o quadro Timegrapher do relógio): cada medição de um timegrapher de bancada numa posição (a marcha, a amplitude, o erro de batida, as batidas por hora e o ângulo de levantamento), digitada ou importada do CSV do aparelho; a última sessão (as medições do mesmo dia), com a média de cada grandeza e a diferença de marcha entre as posições; as grandezas e as posições dos formulários; e as colunas e os nomes das posições que a importação entende (csv). Sem o relógio, as medições de todos. Gravar: escrita timegrapher')],
        "relatorios" => ["descricao" => t('os relatórios, por uma porta só (a página Relatórios): sem tipo, o catálogo (cada relatório com o grupo, o nome, a descrição e os parâmetros que aceita, e os relógios para o parâmetro relogio); com tipo, o relatório pronto, num formato só para todos: o título, o subtítulo (o que foi pedido, em texto), a foto, o resumo (pares), as seções (tabela, com as colunas, as linhas e o total; ou pares) e o rodapé, tudo em texto, no idioma de quem pede. Os tipos: colecao (o inventário), passaporte (a ficha de um relógio), custos, desejos, acessorios, documentos, historico (a linha do tempo), estatisticas (o uso no período), plano, avisos, criterios (as notas), servicos, precisao, timegrapher, reserva, calibres, totais e cron. Cada um é montado com o mesmo recurso que a tela usa (as mesmas regras de acesso)'),
            "parametros" => ["tipo" => t('o relatório (um do catálogo; sem ele: o catálogo; outro: 404 com os tipos)'), "relogio" => t('o id do relógio, nos relatórios que aceitam (no passaporte, obrigatório; o que não existe: 404)'),
                "de" => t('o começo do período (AAAA-MM-DD), nos que aceitam; sem ele, o padrão do relatório'), "ate" => t('o fim do período (AAAA-MM-DD)'),
                "posse" => t('no inventário: colecao (o padrão) ou todos'), "situacao" => t('nas execuções do cron: atividade (o padrão), todas ou erros'),
                "csv" => t('1: o relatório numa planilha (CSV em UTF-8, separado por ponto e vírgula, para baixar), em vez do JSON')],
            "exemplo" => t('curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=relatorios&tipo=servicos&relogio=3&de=2026-01-01"')],
        "reserva" => ["descricao" => t('a reserva medida (o quadro Reserva medida do relógio): os testes da reserva de marcha do mecânico (quando ficou cheio, por qual protocolo, quando parou e as horas de cheio até parado), as observações da energia (parou, o indicador de carga baixa, outra; também no solar, que não se calibra), a medida (a mediana dos testes, a estimativa do relógio, sem mexer no calibre), o que "Usar a medida" gravaria no cadastro dele e a tabela declarado, medido e estimado com a confiança. Sem o relógio, os testes e as observações de todos. Gravar: escrita reserva'),
            "parametros" => ["relogio" => t('o id: a reserva desse relógio (sem ele: os registros de todos)')],
            "exemplo" => t('curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=reserva&relogio=3"')],
        "passaporte" => ["descricao" => t('o passaporte de um relógio (a página Passaporte, para imprimir ou guardar em PDF), tudo já em texto: quem ele é, o cadastro preenchido (cada valor formatado pelo tipo: data, sim/não, número com a unidade, R$), a compra, o uso (a primeira e a última vez no pulso, as horas no pulso, os dias de uso e o custo por uso), as manutenções (cada tipo de marcação, quantas vezes e a última; as revisões e trocas de pilha), os acessórios, os documentos e os próximos avisos; relógio que não existe: 404'),
            "parametros" => ["relogio" => t('o id do relógio (obrigatório)')],
            "exemplo" => t('curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=passaporte&relogio=3"')],
        "galeria" => ["descricao" => t('a coleção em fotos, por grupo (a página Galeria, para ver e imprimir): cada relógio com a foto, a marca, a referência, o ano e o valor da compra e os dias de uso, e os totais'),
            "parametros" => ["posse" => t('todos: também os desejados, vendidos e arquivados (sem ele: os da coleção, na coleção e emprestados)')],
            "exemplo" => t('curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=galeria&posse=todos"')],
        "textos" => ["descricao" => t('os textos das telas no idioma do pedido (o dicionário da função t() do api.js: o texto em português => a tradução), o idioma, o locale das datas e dos números, o padrão da instalação e os idiomas do sistema. Responde sem login (é só o texto da interface). O idioma de qualquer pedido: lingua=, senão o cookie lingua (o seletor do menu), senão o padrão da instalação (config.idioma), senão o Accept-Language, senão português; toda resposta da API sai nele'),
            "parametros" => ["lingua" => "pt-BR, en, zh-CN, hi, es ou fr", "formato" => t('js: um script (window.TEXTOS_API = {...}), que as páginas carregam antes dos outros')],
            "exemplo" => t('curl "http://servidor/relojoeiro/api.php?recurso=textos&lingua=en"')],
        "proximos" => ["descricao" => t('os Próximos dias da página Hoje, uma página (de hoje até o fim do plano, com os dias livres no meio): a troca de página da tela lê só eles'),
            "parametros" => ["pagina" => t('a página (padrão 1)'), "por_pagina" => t('quantos dias por página (sem ele: o Mostrar até da Configuração, padrão 7)')],
            "exemplo" => t('curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=proximos&pagina=2"')],
        "roteiro" => ["descricao" => t('testa um roteiro de modo de rodízio num dia, sem gravar (o "Testar em todos os relógios" da página Modos de rodízio): roteiro (o texto, as linhas "nome = expressão") ou modo (o id: o roteiro efetivo dele), dia (AAAA-MM-DD, de hoje até um ano à frente; padrão hoje). Cada relógio disponível com as linhas calculadas e as cinco saídas, e quem sairia nesse dia pela mesma escolha do rodízio (o de ontem fora, sem o ciclo), com os dias anteriores do plano contados como uso. Roteiro com erro: as linhas boas valem e os erros vêm em erros'),
            "exemplo" => t('curl -u lucas:senha -G --data-urlencode "roteiro=candidato = NO_GRUPO(\"Tradicional\")" -d dia=2026-10-20 "http://servidor/relojoeiro/api.php?recurso=roteiro"')],
        "rodizio_manual" => ["descricao" => t('o Rodízio manual (o quadro Modo de rodízio da página Hoje): os dias de um período, de 7 em 7, cada um com o que o plano tem agora e a escolha de partida do seletor (o relógio escolhido à mão, livre ou auto: Decida por mim), os relógios disponíveis e o critério do Decida por mim. Gravar: recurso=rodizio, acao=manual'),
            "parametros" => ["de, ate" => t('datas AAAA-MM-DD, de hoje em diante, até 2 anos (obrigatórias; inválidas: 400 com erro)'), "pagina" => t('1, 2...: a página de 7 dias (padrão 1)')],
            "exemplo" => t('curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=rodizio_manual&de=2026-12-20&ate=2027-01-05&pagina=2"')],
        "eventos" => ["descricao" => t('os eventos personalizados da coleção, com quando disparam, os destinos e as agendas que recebem cada um, as 10 próximas ocorrências e os disparos'),
            "parametros" => [],
            "exemplo" => t('curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=eventos"')],
        "destinos" => ["descricao" => t('os destinos das mensagens da coleção (a página Destinos): cada um (webhook HTTP, e-mail ou Web Push) com o nome, se está ligado, a mensagem padrão, o idioma, o que recebe (cada tipo de aviso e cada evento, com o modelo próprio), o que é do tipo dele (o webhook: método, endereço, formato, campos, corpo JSON e os cabeçalhos, sem o valor; o e-mail: para quem; o Web Push: o usuário e quantos aparelhos dele) e a prévia de hoje (o que sairia de manhã e à noite); os tipos, os avisos, as âncoras, os idiomas, a mensagem padrão do modelo, se o e-mail e o Web Push estão configurados no servidor e quem vê a coleção (para o Web Push)'),
            "parametros" => [],
            "exemplo" => t('curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=destinos"')],
        "agendas" => ["descricao" => t('as agendas da coleção (a página Agendas): cada uma (Google Agenda, CalDAV, Outlook ou link ICS) com o nome, se está ativa, a janela em dias, o modelo do evento, o idioma, o que recebe, o que é do tipo dela (sem os segredos: só se estão preenchidos; o link ICS sai inteiro), quantos eventos o sistema criou nela e a prévia (os primeiros eventos que têm de estar nela agora); os tipos, os avisos, as âncoras, os idiomas, o padrão do modelo e se o Outlook está configurado no servidor (com o endereço de retorno para registrar o aplicativo na Microsoft)'),
            "parametros" => [],
            "exemplo" => t('curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=agendas"')],
        "ics" => ["descricao" => t('o calendário de uma agenda do tipo link ICS (text/calendar, não é JSON), para assinar em qualquer app de agenda: responde sem login, pela chave secreta do link (quem tem o link vê os eventos; Gerar outro link, na página Agendas, desliga o antigo); chave desconhecida: 404'),
            "parametros" => ["chave" => t('a chave do link (vem pronta no link da agenda)')],
            "exemplo" => t('curl "http://servidor/relojoeiro/api.php?recurso=ics&chave=Xy3..."')],
        "outlook_retorno" => ["descricao" => t('a volta da página da Microsoft depois de Conectar ao Outlook (com code e state): guarda a conexão na agenda e leva para a página Agendas com o recado (302). É o endereço de retorno que se registra no aplicativo da Microsoft (OUTLOOK_CLIENTE_ID); não é para chamar à mão'),
            "parametros" => ["code" => t('o código que a Microsoft manda'), "state" => t('a agenda e a assinatura dela')],
            "exemplo" => t('(a Microsoft chama: http://servidor/relojoeiro/api.php?recurso=outlook_retorno&code=...&state=...)')],
        "foto" => ["descricao" => t('a foto de um relógio (a imagem, não é JSON)'),
            "parametros" => ["relogio" => t('o id do relógio')],
            "exemplo" => t('curl -u lucas:senha -o foto.jpg "http://servidor/relojoeiro/api.php?recurso=foto&relogio=10"')],
        "documentos" => ["descricao" => t('os documentos de um relógio (ou de todos), de um calibre ou de um winder: o manual, a nota fiscal em PDF e em XML (com o resumo da NF-e), fotos, vídeos e o que mais for, com as categorias (e quantos documentos cada uma tem), os relógios, os calibres e os winders (com quantos), se a pasta dos documentos está pronta, se a cópia de segurança no banco está ligada, onde está cada arquivo (na pasta, no banco) e o maior arquivo aceito'),
            "parametros" => ["relogio" => t('o id do relógio (sem ele: de todos)'),
                "calibre" => t('o id de um calibre: os documentos dele (o manual técnico, a ficha de serviço...), que valem para todos os relógios com ele; um que não existe: 404'),
                "winder" => t('o id de um winder: os documentos dele (o manual, a nota, as fotos); um que não existe: 404')],
            "exemplo" => t('curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=documentos&relogio=10"')],
        "documento" => ["descricao" => t('o arquivo de um documento (não é JSON): imagens, vídeos, áudios, PDF e texto vêm para mostrar; o resto (inclusive XML, HTML e SVG), para baixar; aceita o pedido de um pedaço (Range), que o vídeo usa para avançar; se o arquivo sumiu da pasta, ou está cortado (o tamanho não confere com o do envio), ele é recriado antes a partir da cópia no banco'),
            "parametros" => ["id" => t('o id do documento'), "baixar" => t('1: sempre para baixar'), "mini" => t('1: a miniatura da foto (sem ela, a foto)')],
            "exemplo" => t('curl -u lucas:senha -o nota.pdf "http://servidor/relojoeiro/api.php?recurso=documento&id=7"')],
        "usuarios" => ["descricao" => t('para o master, o painel das contas: cada usuário com o login, o e-mail, o papel (master ou comum), o idioma, quando foi criado, o último acesso, quando vence (a conta de demonstração) e quantos dias faltam, se está bloqueado, as coleções dele (com quantos relógios), as de que é membro, de quem vê tudo, quantos pedidos e tokens tem e o hash da senha (o algoritmo e o custo, para migrar com a mesma senha: veja senhas); e as coleções todas e os dias da demonstração. Para os outros, só a própria conta (o login, quando foi criada e o hash). A senha não existe no sistema'),
            "parametros" => [],
            "exemplo" => t('curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=usuarios"')],
        "conta" => ["descricao" => t('Minha conta: quem eu sou (o login, o e-mail, o papel, o idioma, se é demonstração e quantos dias faltam), a faixa Vendo como (o master vendo como outro usuário), as coleções que eu vejo (com o dono e o meu papel em cada uma) e a do pedido, as minhas árvores de grupos (com as coleções que usam cada uma), os meus pedidos de acesso esperando, os convites para o meu e-mail, quantas aprovações esperam por mim, os meus tokens de API (sem o token, que só aparece ao criar), os meus aparelhos lembrados (o aplicativo no celular), os meus aparelhos do Web Push e a chave pública dele, se o servidor manda e-mail, os dias da demonstração e os idiomas. Com parte=menu, só o que o menu das páginas usa (o seletor da coleção, o aviso da demonstração, as aprovações, a faixa Vendo como, o idioma padrão e o modo da interface, com o que fica de fora nele)'),
            "parametros" => ["parte" => t('menu: só o pedaço do menu das páginas')],
            "exemplo" => t('curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=conta"')],
        "colecoes" => ["descricao" => t('as coleções que eu vejo (cada uma com o dono, o meu papel e a raiz da árvore dela), a coleção do pedido e as minhas árvores de grupos (com quantos grupos e as coleções que usam cada uma). Gravar: escrita colecoes'),
            "parametros" => [],
            "exemplo" => t('curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=colecoes"')],
        "aprovacoes" => ["descricao" => t('a página Aprovações: os pedidos de acesso que eu aprovo (os das minhas coleções e os de tudo meu; o master, todos), os convites de membros que esperam por mim, os convites que eu fiz, quem vê as minhas coleções (os membros de cada uma e quem tem tudo meu), as minhas coleções, para onde posso convidar, se o servidor manda e-mail e quantos dias um convite vale'),
            "parametros" => [],
            "exemplo" => t('curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=aprovacoes"')],
        "cadastro" => ["descricao" => t('o cadastro aberto (a página cadastro.php), sem login: se está aberto (CADASTRO_ABERTO), os dias da demonstração, se o servidor manda e-mail, os idiomas e, com ele aberto, as coleções e os donos (para pedir acesso); com convite=<token>, o convite (o e-mail, o que ele dá, até quando e se o e-mail já tem conta; false: o convite não vale mais). Gravar: escrita cadastro'),
            "parametros" => ["convite" => t('o token do link do convite')],
            "exemplo" => t('curl "http://servidor/relojoeiro/api.php?recurso=cadastro"')],
        "migracoes" => ["descricao" => t('as migrações que faltam aplicar no banco (lista vazia: está em dia); com o banco desatualizado, só ele (e o manual e o código, que não usam o banco) responde'),
            "parametros" => [],
            "exemplo" => t('curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=migracoes"')],
        "instalacao" => ["descricao" => t('a situação da instalação: o banco, se está vazio, instalado e em dia, as migrações que faltam, quantos usuários há e o próximo passo (instalar, aplicar as migrações, criar o primeiro usuário ou nada); responde também com o banco vazio, pelo token'),
            "parametros" => [],
            "exemplo" => t('curl -H "X-Api-Token: segredo" "http://servidor/relojoeiro/api.php?recurso=instalacao"')],
        "importacao" => ["descricao" => t('o que a importação do sistema anterior usa: o servidor do banco antigo (sem a senha) e de onde ele vem no config.php, se o PHP tem a extensão do MySQL, quantos relógios este banco já tem (com algum, a importação pede substituir=1) e o que ela traz'),
            "parametros" => [],
            "exemplo" => t('curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=importacao"')],
        "backup" => ["descricao" => t('a cópia de segurança do banco (uma por dia, na rodada da noite do cron, na BACKUP_PASTA do config.php): se a pasta serve, quantas cópias ficam, se levam o conteúdo dos documentos, a versão do banco, a última e as cópias da pasta (da mais nova para a mais velha); com arquivo=<nome>, baixa aquela cópia (JSON Lines comprimido, o mesmo nos quatro bancos). Fazer e restaurar: na escrita'),
            "parametros" => ["arquivo" => t('o nome de uma cópia (relojoeiro-AAAA-MM-DD-HHMMSS.jsonl.gz): baixa o arquivo')],
            "exemplo" => t('curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=backup"')],
        "manifest" => ["descricao" => t('o manifesto do aplicativo no celular (PWA; application/manifest+json): o nome, o ícone, as cores, o start_url e o scope. Responde sem login (o navegador pede ao instalar); com o cookie do aparelho lembrado (Minha conta, Lembrar este aparelho), o start_url leva a chave dele (index.php?aparelho=...): o aplicativo instalado abre já entrando, também no iPhone, onde o aplicativo não compartilha os cookies do Safari'),
            "exemplo" => t('curl "http://servidor/relojoeiro/api.php?recurso=manifest"')],
        "sw" => ["descricao" => t('o service worker do aplicativo (JavaScript, não é JSON): o sw.js com, na frente, a versão (muda quando qualquer arquivo das telas muda) e a lista dos arquivos guardados na instalação (o estilo, os scripts, os ícones e a página sem conexão). Responde sem login. Guarda os arquivos das telas e os textos do idioma; as páginas o navegador abre direto da rede, sem passar por ele (assim o pedido de senha do login aparece; sem rede, a página offline.html) e a API nunca fica em cache; recebe o Web Push'),
            "exemplo" => t('curl "http://servidor/relojoeiro/api.php?recurso=sw"')],
        "entrar" => ["descricao" => t('o login das páginas: sem login, 401 (o navegador pede o usuário e a senha); com login, vai para a página de volta (302) ou diz quem entrou (usuario, por, volta). É para onde o api.js manda quem abre uma página sem login'),
            "parametros" => ["volta" => t('uma página do sistema para onde ir depois de entrar (index.php, plano.php?..., ajuda.php#...); outra coisa não vale')],
            "exemplo" => t('no navegador: http://servidor/relojoeiro/api.php?recurso=entrar&volta=index.php')],
        "autonomia" => ["descricao" => t('as autonomias de cada relógio, enxuto e rápido, para sistemas de fora, em segundos inteiros: prevista (cheio, pelo cadastro), atual (cheio, pela conta do sistema com o gasto medido), estimada (quanto ainda dura seguindo o plano), restante_em_uso (no pulso sem tirar), restante_guardado (parado) e quando acaba (acaba_em_unixtimestamp, acaba_em_segundos, acaba_em_datacomtz); null com o motivo em motivos'),
            "parametros" => ["relogio" => t('um id ou vários separados por vírgula (vazio: todos)')],
            "exemplo" => t('curl -u lucas:senha -g "http://servidor/relojoeiro/api.php?recurso=autonomia&f[relogios][acaba_em_segundos][ate]=86400&mostrar[relogios]=nome,acaba_em_datacomtz"')],
        "ajuda" => ["descricao" => t('esta explicação: os recursos, os parâmetros, as ações de escrita com os campos, os exemplos, o dicionário de todos os campos (campos) e as funções do motor; com parte=manual, o manual (veja manual); com parte=reconstrucao, a reconstrução (veja reconstrucao); com parte=codigo, o código (veja codigo)'),
            "parametros" => ["parte" => t('manual: em vez desta explicação, o texto da página Ajuda (o mesmo que recurso=manual); reconstrucao: o roteiro para reescrever a aplicação do zero (o mesmo que recurso=reconstrucao); codigo: o código do sistema (o mesmo que recurso=codigo)')],
            "exemplo" => t('curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=ajuda&parte=reconstrucao"')],
        "manual" => ["descricao" => t('o texto da página Ajuda: os trechos do README para quem usa (a ideia central, como funciona, o cadastro campo por campo, a Configuração, um dia com o sistema, as telas, as perguntas frequentes e como reescrever o sistema do zero), em markdown, inteiro e seção por seção (título, nível, âncora e texto), e já em HTML com o sumário, como a página Ajuda mostra; sem o README.md na pasta: 404; responde mesmo com o banco desatualizado. O mesmo que recurso=ajuda&parte=manual'),
            "parametros" => [],
            "exemplo" => t('curl -u lucas:senha -g "http://servidor/relojoeiro/api.php?recurso=manual&mostrar[secoes]=titulo,ancora"')],
        "reconstrucao" => ["descricao" => t('o roteiro para reescrever a aplicação inteira do zero, em qualquer linguagem e banco, chegando ao mesmo sistema: o que ele é, os princípios, a arquitetura, a ordem de construção e as regras de cada parte (árvore e campos, lançamentos, fórmulas, avisos, gasto medido, critérios, rodízio e escala, pulso sozinho, cron, mensagens e agenda, documentos, telas, segurança, testes), a especificação visual de cada tela (telas: o visual com os valores exatos, o menu e cada página com as tabelas, os campos, os botões e as mensagens), a lista do código do sistema (codigo: o mesmo do recurso=codigo, que traz cada arquivo como está agora), o modelo de dados lido do próprio banco (tabelas, colunas, chaves, índices e regras de validação) e as listas do código (funções das fórmulas, tipos de campo, formatos de lançamento, repetições, dias da semana, âncoras, canais, migrações e as constantes do config.php). O mesmo que recurso=ajuda&parte=reconstrucao'),
            "parametros" => [],
            "exemplo" => t('curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=reconstrucao"')],
        "codigo" => ["descricao" => t('o código do sistema como está agora, lido do disco na hora do pedido, para a reescrita ler o original: cada arquivo (as páginas, o estilo, o JavaScript, a API, o núcleo, o banco, as migrações, o servidor, os testes, a documentação e as capturas das telas) com a camada, o que ele é, a linguagem, o tamanho, as linhas, o SHA-256 e a data; nas páginas, os arquivos que ela carrega e o HTML que o navegador recebe; e o que fica de fora de propósito (o config.php, a chave do Google, o banco, os documentos, as senhas), com o que ver no lugar. Só saem os arquivos do sistema (os do repositório); responde mesmo com o banco vazio ou desatualizado. O mesmo que recurso=ajuda&parte=codigo'),
            "parametros" => ["arquivo" => t('um arquivo (o nome como está em arquivos, ex.: estilo.css, docs/telas/hoje.png): vem com o conteúdo como está (conteudo; a imagem em conteudo_base64) e, numa página, com o HTML que o navegador recebe (html)'),
                "cru" => t('1, com arquivo: o arquivo puro, sem JSON (texto como text/plain, para ler no navegador; imagem como imagem)'),
                "html" => t('1, com arquivo de uma página e cru=1: o HTML que o navegador recebe, puro'),
                "conteudo" => t('1, sem arquivo: a lista com o conteúdo de todos (com f[arquivos][camada]=tela, só o das telas)')],
            "exemplo" => t('no navegador: http://servidor/relojoeiro/api.php?recurso=codigo&arquivo=estilo.css&cru=1')],
    ],
    "escrita" => [
        "como" => t('POST, com os campos em formulário ou em JSON no corpo (Content-Type: application/json); recurso e acao nos campos ou na URL. Resposta: {ok, mensagem, erros, id}; 400 quando recusado (os erros dizem por quê). Ex. em JSON: curl -u lucas:senha -H "Content-Type: application/json" -d \'{"recurso":"lancamento","acao":"lancar","relogio_id":10,"tipo":"carga","valor":68}\' http://servidor/relojoeiro/api.php'),
        "arvore" => [
            "novo" => ["campos" => t('nome, pai_id (0 = na raiz)'), "exemplo" => t('curl -u lucas:senha -d recurso=arvore -d acao=novo -d "nome=Cronógrafos" -d pai_id=2 http://servidor/relojoeiro/api.php')],
            "renomear" => ["campos" => t('id, nome'), "exemplo" => t('curl -u lucas:senha -d recurso=arvore -d acao=renomear -d id=5 -d "nome=Automáticos" http://servidor/relojoeiro/api.php')],
            "mover" => ["campos" => t('id, pai_id (0 = na raiz; não pode ir para dentro dele mesmo)'), "exemplo" => t('curl -u lucas:senha -d recurso=arvore -d acao=mover -d id=5 -d pai_id=0 http://servidor/relojoeiro/api.php')],
            "ordem" => ["campos" => t('id, direcao (sobe ou desce)'), "exemplo" => t('curl -u lucas:senha -d recurso=arvore -d acao=ordem -d id=5 -d direcao=sobe http://servidor/relojoeiro/api.php')],
            "excluir" => ["campos" => t('id; o que é dele (subgrupos, relógios, campos, tipos de lançamento, fórmulas, avisos) sobe para o de cima, menos as versões de fórmulas e avisos que o de cima já tem (essas saem); os blocos dos modos que sorteavam dele passam a sortear do de cima; os critérios próprios saem (os relógios usam os do lugar mais perto, acima)'), "exemplo" => t('curl -u lucas:senha -d recurso=arvore -d acao=excluir -d id=5 http://servidor/relojoeiro/api.php')],
            "relogios" => ["campos" => t('grupo[<id do relógio>] = o grupo (0 = na raiz), um ou vários'), "exemplo" => t('curl -u lucas:senha -d recurso=arvore -d acao=relogios -d "grupo[13]=1" -d "grupo[4]=8" http://servidor/relojoeiro/api.php')],
        ],
        "campos" => [
            "novo" => ["campos" => t('identificador, nome, tipo (inteiro, decimal, sim_nao, data, lista, texto), unidade (o símbolo de uma unidade cadastrada, recurso=unidades; vazio: nenhuma), opcoes (os valores possíveis, um por linha: na lista, obrigatórios; no texto e no número, o valor tem de ser um deles; no sim/não e na data, não valem), minimo e maximo (só no número; vazio: sem limite), multiplo (1: vários dos valores possíveis de uma vez, como as funções; precisa dos valores possíveis), padrao, no_id (0 = todos), secao_id (a divisória da ficha, recurso=cadastros, secoes; 0: nenhuma, no fim), so_desejado (1: o campo vale só nos relógios desejados, a lista de desejos; padrão 0), calibre (1: o campo é do movimento e aparece no formulário do calibre; padrão 0), alvo (relogio, o padrão; acessorio: o campo é do cadastro do acessório; winder: do winder; posicao: da posição do winder, nas fórmulas por WINDER_POSICAO("identificador"); fora do relógio, no_id, secao_id, so_desejado e calibre não valem; só muda sem valores gravados), acessorio_tipo (no de acessório, o tipo em que ele vale; vazio: todos), serve_campo_id (no de acessório, o campo do relógio com que ele tem de bater para o acessório servir no relógio: a largura da pulseira com o entre alças; 0: nenhum)'), "exemplo" => t('curl -u lucas:senha -d recurso=campos -d acao=novo -d identificador=resistencia_agua -d "nome=Resistência à água" -d tipo=inteiro -d unidade=m -d no_id=0 http://servidor/relojoeiro/api.php')],
            "alterar" => ["campos" => t('id e os mesmos campos (só o que vier muda)'), "exemplo" => t('curl -u lucas:senha -d recurso=campos -d acao=alterar -d id=21 -d "nome=Resistência (m)" http://servidor/relojoeiro/api.php')],
            "ordem" => ["campos" => t('id, direcao (sobe ou desce)'), "exemplo" => t('curl -u lucas:senha -d recurso=campos -d acao=ordem -d id=21 -d direcao=sobe http://servidor/relojoeiro/api.php')],
            "excluir" => ["campos" => t('confirmar=1; id (os valores dele saem junto)'), "exemplo" => t('curl -u lucas:senha -d recurso=campos -d acao=excluir -d id=21 -d confirmar=1 http://servidor/relojoeiro/api.php')],
        ],
        "lancamento_tipos" => [
            "novo" => ["campos" => t('identificador, nome, formato (instantaneo, valor, sessao), unidade (com valor: o símbolo de uma unidade cadastrada, recurso=unidades), fecha_as (sessão: HH:MM; vazio: não fecha sozinha), exclusiva (1 ou 0, só sessão), mede_gasto (1 ou 0, só com valor: cada leitura mede o gasto, comparando com a anterior), marcha (desvio: só com valor, a leitura do desvio da hora em segundos; acerto: só instantâneo, o acerto da hora; vazio: nenhum dos dois), winder (1 ou 0, só sessão: a sessão é numa posição de um winder, e o Pôr pede a posição), condicao (vale quando: uma fórmula, 1 vale e 0 não; vazia, vale sempre; ex.: corda_manual), no_id'), "exemplo" => t('curl -u lucas:senha -d recurso=lancamento_tipos -d acao=novo -d identificador=banho_ultrassom -d "nome=Banho ultrassônico" -d formato=instantaneo -d no_id=0 http://servidor/relojoeiro/api.php')],
            "alterar" => ["campos" => t('id e os mesmos campos'), "exemplo" => t('curl -u lucas:senha -d recurso=lancamento_tipos -d acao=alterar -d id=11 -d fecha_as=18:00 http://servidor/relojoeiro/api.php')],
            "excluir" => ["campos" => t('confirmar=1; id (só sem lançamentos)'), "exemplo" => t('curl -u lucas:senha -d recurso=lancamento_tipos -d acao=excluir -d id=11 -d confirmar=1 http://servidor/relojoeiro/api.php')],
        ],
        "formulas" => [
