            "alterar" => ["campos" => t('id: nome, expressao, unidade, no_id'), "exemplo" => t('curl -u lucas:senha -d recurso=formulas -d acao=alterar -d id=17 --data-urlencode "expressao=ARREDONDA(AGORA() - data_compra)" http://servidor/relojoeiro/api.php')],
            "excluir" => ["campos" => t('confirmar=1; id (a versão)'), "exemplo" => t('curl -u lucas:senha -d recurso=formulas -d acao=excluir -d id=17 -d confirmar=1 http://servidor/relojoeiro/api.php')],
