        "totais" => [
            "salvar" => ["campos" => t('id (0 cria), coluna (a chave de uma coluna da tabela dos relógios: codigo, nome, tipo, estado, carga, ultimo, manut, em, fazer, encostado, compra ou valor; vazio: nenhuma), nome, expressao (uma expressão de total: as funções de total em recurso=totais, funcoes), rodape (1 ou 0: no rodapé, embaixo da coluna; só com coluna), pagina (1 ou 0: na página de totais; pelo menos um dos dois), largura (estreito ou largo: o quadro na página de totais), formato (numero, inteiro, decimal, moeda, porcentagem, data ou dias); só o que vier muda'), "exemplo" => t('curl -u lucas:senha -d recurso=totais -d acao=salvar -d id=0 -d coluna=valor -d nome="Valor por tipo" --data-urlencode "expressao=AGRUPADO(tipo; SOMA(valor_compra))" -d rodape=1 -d pagina=1 -d formato=moeda http://servidor/relojoeiro/api.php')],
            "excluir" => ["campos" => t('confirmar=1; id'), "exemplo" => t('curl -u lucas:senha -d recurso=totais -d acao=excluir -d id=4 -d confirmar=1 http://servidor/relojoeiro/api.php')],
            "subir" => ["campos" => t('id: troca de lugar com o de cima na ordem (a ordem embaixo de cada coluna e dos quadros da página)'), "exemplo" => t('curl -u lucas:senha -d recurso=totais -d acao=subir -d id=4 http://servidor/relojoeiro/api.php')],
            "descer" => ["campos" => t('id: troca de lugar com o de baixo'), "exemplo" => t('curl -u lucas:senha -d recurso=totais -d acao=descer -d id=4 http://servidor/relojoeiro/api.php')],
        ],
        "secoes" => [
            "salvar" => ["campos" => t('id (0 cria, no fim), nome (até 80, sem repetir na árvore): a divisória da ficha, que agrupa os campos no cadastro, no painel, no passaporte e nos relatórios'),
                "exemplo" => t('curl -u lucas:senha -d recurso=secoes -d acao=salvar -d id=0 -d nome=Pulseira http://servidor/relojoeiro/api.php')],
            "ordem" => ["campos" => t('id, direcao (sobe ou desce)'), "exemplo" => t('curl -u lucas:senha -d recurso=secoes -d acao=ordem -d id=8 -d direcao=sobe http://servidor/relojoeiro/api.php')],
            "excluir" => ["campos" => t('confirmar=1; id: os campos dela ficam sem divisória, no fim da ficha'), "exemplo" => t('curl -u lucas:senha -d recurso=secoes -d acao=excluir -d id=8 -d confirmar=1 http://servidor/relojoeiro/api.php')],
