        "unidades" => [
            "salvar" => ["campos" => t('id (0 cria), simbolo (até 20, sem repetir na árvore: o que vai depois do número), nome (até 80), base (o símbolo da unidade base, a da mesma grandeza em que esta se converte, que não tem base; vazio: esta é uma base), fator (com base: 1 desta = fator da base), zero (com base: o valor desta que é o zero da base, como os 32 do °F; vazio: 0), mostrar_em (o símbolo de uma unidade da mesma grandeza em que o valor também aparece, na ficha e no passaporte; vazio: nenhuma); só muda o que vier. O símbolo novo vai junto para os campos, os tipos de lançamento e as fórmulas que usavam o antigo'),
                "exemplo" => t('curl -u lucas:senha -d recurso=unidades -d acao=salvar -d id=0 -d simbolo=mi -d nome=milha -d base=mm -d fator=1609344 http://servidor/relojoeiro/api.php')],
            "excluir" => ["campos" => t('confirmar=1; id: as unidades que se convertem nela saem junto; recusada se ela (ou uma dessas) está em uso num campo, num tipo de lançamento ou numa fórmula'), "exemplo" => t('curl -u lucas:senha -d recurso=unidades -d acao=excluir -d id=33 -d confirmar=1 http://servidor/relojoeiro/api.php')],
        ],
        "calibres" => [
