                "exemplo" => t('curl -u lucas:senha -d recurso=calibres -d acao=salvar -d id=0 -d nome=NH35 -d fabricante=Seiko -d "valores[reserva_horas]=41" http://servidor/relojoeiro/api.php')],
            "excluir" => ["campos" => t('confirmar=1; id: os relógios que apontam para ele ficam sem calibre'), "exemplo" => t('curl -u lucas:senha -d recurso=calibres -d acao=excluir -d id=3 -d confirmar=1 http://servidor/relojoeiro/api.php')],
        ],
        "relogio" => [
            "salvar" => ["campos" => t('id (0 ou ausente cria), nome, no_id, disponivel (1 ou 0), copia_banco (1 ou 0: a cópia no banco de todos os documentos dele; o cron copia ou tira aos poucos), posse (a situação na coleção: o identificador de um item da lista Situações do relógio na coleção, Cadastros › Listas; o padrão, a primeira que faz colecao; o que ela faz vem do item: colecao, emprestado, desejado ou fora. Fora da coleção o relógio fica indisponível (disponivel=1 é ignorado, com uma nota), e, saindo dela, as sessões abertas dele (no pulso, no sol...) fecham agora e os dias dele no plano de amanhã em diante saem e são sorteados de novo (hoje fica, mas ele não vai ao pulso sozinho); voltando para ela sem disponivel, fica disponível; em manutenção, o disponivel pedido é o da volta), valores[<identificador do campo>]: só muda o que vier; valor vazio apaga (os campos só nos desejados, como o preco_alvo, só gravam no desejado; no campo múltiplo, valores[<identificador>][] uma vez para cada valor, ou um por linha; o valor tem de seguir as regras do campo: os valores possíveis, o mínimo e o máximo); calibre_id: o calibre (o movimento) dele, um do recurso=calibres (0 ou vazio tira)'), "exemplo" => t('curl -u lucas:senha -d recurso=relogio -d acao=salvar -d id=10 -d "valores[preferencia]=80" -d disponivel=1 http://servidor/relojoeiro/api.php')],
            "foto" => ["campos" => t('id, foto_base64 (JPEG, PNG ou WebP, até 4 MB; data:image/...;base64,... ou só o base64)'), "exemplo" => t('curl -u lucas:senha -d recurso=relogio -d acao=foto -d id=10 --data-urlencode foto_base64@foto.b64 http://servidor/relojoeiro/api.php')],
            "remover_foto" => ["campos" => "id", "exemplo" => t('curl -u lucas:senha -d recurso=relogio -d acao=remover_foto -d id=10 http://servidor/relojoeiro/api.php')],
            "excluir" => ["campos" => t('confirmar=1; id (com todo o histórico, a foto e os documentos, inclusive os arquivos deles; os acessórios dele ficam soltos)'), "exemplo" => t('curl -u lucas:senha -d recurso=relogio -d acao=excluir -d id=15 -d confirmar=1 http://servidor/relojoeiro/api.php')],
        ],
        "documentos" => [
            "enviar" => ["campos" => t('relogio_id, categoria_id, titulo (vazio: o nome do arquivo), data (AAAA-MM-DD), descricao, copia_banco (1: pede a cópia destes arquivos no banco; o config.php e o relógio, se pedem, valem por cima) e o arquivo: arquivos[] (upload; vários de uma vez) ou arquivo_base64 com arquivo_nome; a miniatura de uma foto, opcional: miniatura (upload, JPEG, PNG ou WebP até 1 MB) ou miniatura_base64. Cada arquivo até o limite (recurso=documentos, limite) e do tipo que a categoria aceita. O arquivo vai para a pasta e, se a cópia é pedida (pelo config.php, pelo relógio ou pelo próprio arquivo), também para o banco, em pedaços de 4 MB (se a cópia falhar, o documento fica e a mensagem avisa; o cron tenta de novo). Responde ids: os documentos guardados; calibre_id no lugar de relogio_id: o documento é do calibre (vale para todos os relógios com ele; o arquivo vai para a pasta c<id>); winder_id no lugar de relogio_id: o documento é do winder (o manual, a nota, as fotos; a pasta w<id>); dois deles juntos: recusado'),
                "exemplo" => t('curl -u lucas:senha -F recurso=documentos -F acao=enviar -F relogio_id=10 -F categoria_id=2 -F "arquivos[]=@nota.pdf" http://servidor/relojoeiro/api.php')],
            "alterar" => ["campos" => t('id, categoria_id, titulo, data, descricao, copia_banco (1 ou 0): só muda o que vier; a cópia entra ou sai do banco na hora (só sai se o arquivo da pasta confere com ela)'), "exemplo" => t('curl -u lucas:senha -d recurso=documentos -d acao=alterar -d id=7 -d "titulo=No casamento" -d data=2026-09-20 http://servidor/relojoeiro/api.php')],
            "excluir" => ["campos" => t('confirmar=1; id: o documento, o arquivo dele na pasta e a cópia no banco'), "exemplo" => t('curl -u lucas:senha -d recurso=documentos -d acao=excluir -d id=7 -d confirmar=1 http://servidor/relojoeiro/api.php')],
        ],
        "acessorios" => [
            "salvar" => ["campos" => t('id (0 ou ausente cria), nome (até 120), tipo (o identificador de um tipo de acessório, Cadastros › Listas; padrão pulseira), relogio_id (o relógio de que ele é; 0: solto, serve a vários), observacao (até 1000), valores[<identificador do campo>]: os campos do acessório do tipo dele (Cadastros › Campos, para acessório; recurso=acessorios, campos), com as regras do valor; vazio apaga; trocar o tipo apaga os que não são do tipo novo: só muda o que vier'), "exemplo" => t('curl -u lucas:senha -d recurso=acessorios -d acao=salvar -d "nome=Pulseira NATO verde" -d tipo=pulseira -d relogio_id=3 -d "valores[pulseira_largura]=20" http://servidor/relojoeiro/api.php')],
            "excluir" => ["campos" => t('confirmar=1; id'), "exemplo" => t('curl -u lucas:senha -d recurso=acessorios -d acao=excluir -d id=4 -d confirmar=1 http://servidor/relojoeiro/api.php')],
        ],
        "winders" => [
            "salvar" => ["campos" => t('id (0 ou ausente cria), nome (até 120), observacao (até 1000), valores[<identificador do campo>]: os campos do winder (Cadastros › Campos, para o winder; recurso=winders, campos_winder: a marca, o modelo, winder_manual, o link do manual, e os limites da almofada, winder_caixa_max, winder_pulso_min, winder_pulso_max e winder_peso_max), com as regras do valor; vazio apaga; e, só ao criar, posicoes (de 0 a 50): as posições que ele já ganha, "Pos. 1", "Pos. 2"...: só muda o que vier'), "exemplo" => t('curl -u lucas:senha -d recurso=winders -d acao=salvar -d "nome=Escritório" -d posicoes=4 -d "valores[winder_marca]=Wolf" http://servidor/relojoeiro/api.php')],
            "limite_ok" => ["campos" => t('id, relogio_id: o aviso de limite da almofada daquele relógio neste winder (a caixa ou o peso passa do que ela aguenta) não volta mais: o "Já sei, deixa assim"'), "exemplo" => t('curl -u lucas:senha -d recurso=winders -d acao=limite_ok -d id=2 -d relogio_id=4 http://servidor/relojoeiro/api.php')],
            "excluir" => ["campos" => t('confirmar=1; id (com as posições, os lugares e os documentos dele, também os arquivos; as sessões que ficaram nelas continuam, sem a posição, e a conta delas volta a usar os campos do relógio)'), "exemplo" => t('curl -u lucas:senha -d recurso=winders -d acao=excluir -d id=2 -d confirmar=1 http://servidor/relojoeiro/api.php')],
        ],
        "winder_posicoes" => [
            "salvar" => ["campos" => t('id (0 ou ausente cria, com winder_id), nome (até 60, sem repetir no winder), ordem, ligada (1 ou 0: a desligada não recebe relógio; com um relógio dentro, só junto com relogio_id=0), programa_id (o programa da posição, da página Programas: recurso=winders, programas; 0 tira), valores[<identificador do campo>]: os campos livres da posição (Cadastros › Campos, para a posição do winder; recurso=winders, campos_posicao), com as regras do valor; vazio apaga e vale o padrão do campo; relogio_id: o relógio que fica na posição (recurso=winders, relogios): quem estava nela sai agora, e o escolhido, se estava noutra posição ou no winder sem posição, sai de lá e entra nesta (a sessão do tipo marcado como winder dele), e a posição passa a ser o lugar dele (o lugar fixo: o lugar que ele tinha fica livre, e quem tinha este perde); 0: tira quem está (o lugar continua dele); sem ele, ninguém entra nem sai: só muda o que vier. Na resposta, avisos: os avisos de limite da almofada do relógio que entrou'), "exemplo" => t('curl -u lucas:senha -d recurso=winder_posicoes -d acao=salvar -d id=5 -d programa_id=2 -d relogio_id=4 http://servidor/relojoeiro/api.php')],
            "liberar" => ["campos" => t('id: a posição deixa de ser o lugar de quem era (o Liberar o lugar); só vazia (com o dono dentro, tire-o antes)'), "exemplo" => t('curl -u lucas:senha -d recurso=winder_posicoes -d acao=liberar -d id=5 http://servidor/relojoeiro/api.php')],
            "excluir" => ["campos" => t('confirmar=1; id (as sessões que ficaram nela continuam, sem a posição)'), "exemplo" => t('curl -u lucas:senha -d recurso=winder_posicoes -d acao=excluir -d id=7 -d confirmar=1 http://servidor/relojoeiro/api.php')],
        ],
        "movimentos" => [
            "salvar" => ["campos" => t('id (0 ou ausente cria; o código do movimento, o que a sequência do programa usa), nome (até 60), tipo (horario, anti_horario ou parado), e a medida: voltas, ou o tempo em minutos e segundos (os dois somam); a parada só tem o tempo, e o giro tem uma das duas, nunca as duas (a outra o programa calcula pela velocidade do berço); só muda o que vier, e a medida que vier troca a de antes. Num movimento que algum programa usa, recusa a mudança que deixaria a conta do programa sem fechar (um giro em voltas num programa por tempo, por exemplo)'), "exemplo" => t('curl -u lucas:senha -d recurso=movimentos -d acao=salvar -d "nome=Giro horário 2 min" -d tipo=horario -d minutos=2 http://servidor/relojoeiro/api.php')],
            "excluir" => ["campos" => t('confirmar=1; id (o que está na sequência de um programa não sai: tire-o de lá antes)'), "exemplo" => t('curl -u lucas:senha -d recurso=movimentos -d acao=excluir -d id=3 -d confirmar=1 http://servidor/relojoeiro/api.php')],
        ],
        "programas" => [
            "salvar" => ["campos" => t('id (0 ou ausente cria), nome (até 80), medida (voltas ou tempo: o tipo de cadastro; os giros da sequência são todos nessa medida), a velocidade do berço, uma ou outra: velocidade (as voltas por minuto, contadas) ou tpd_manual (as voltas por dia que o manual diz, de onde a velocidade sai; as duas juntas: recusado), funciona (dia_todo, ou os blocos: liga_horas e para_horas, as duas), observacao (até 1000), sequencia (os códigos dos movimentos, na ordem: "1, 2, 3, 2"; o mesmo pode repetir); só muda o que vier, e o programa só grava se a conta fecha (tem um giro, e as voltas ou o tempo de cada passo saem). As voltas por dia, o ciclo e o tempo girando não se informam: são calculados (recurso=programas). Na resposta, calculo: o cálculo do programa gravado'), "exemplo" => t('curl -u lucas:senha -d recurso=programas -d acao=salvar -d "nome=Versa 650" -d medida=tempo -d tpd_manual=650 -d funciona=dia_todo -d "sequencia=3, 1, 4, 1" http://servidor/relojoeiro/api.php')],
            "montar" => ["campos" => t('o ajudante "Montar uma sequência": tpd (as voltas por dia que se quer), velocidade (as voltas por minuto do berço), sentido (os_dois, horario ou anti_horario; padrão os_dois), medida (voltas ou tempo; padrão voltas), nome (vazio: as voltas por dia e o sentido, "650 voltas por dia, os dois sentidos"): cria os movimentos que faltam (nos dois sentidos: giro, parada, o outro giro, parada; num só: giro e parada; cada giro com as voltas de mais ou menos uma hora, e as paradas fecham a conta nas voltas pedidas) e o programa, o dia todo, para conferir e mudar. Na resposta, id e calculo'), "exemplo" => t('curl -u lucas:senha -d recurso=programas -d acao=montar -d tpd=650 -d velocidade=5 -d sentido=os_dois http://servidor/relojoeiro/api.php')],
            "excluir" => ["campos" => t('confirmar=1; id (o que está numa posição não sai: troque o programa dela antes; os movimentos dele continuam)'), "exemplo" => t('curl -u lucas:senha -d recurso=programas -d acao=excluir -d id=2 -d confirmar=1 http://servidor/relojoeiro/api.php')],
        ],
        "servicos" => [
            "salvar" => ["campos" => t('id (0 ou ausente cria), relogio_id (só no novo), manutencao_id (só no novo: a manutenção do relógio de que ele é o encerramento; sem ela, uma manutenção já encerrada na oficina oficina_id, sem ela a sua), data (AAAA-MM-DD, até hoje), tipo (o identificador de um tipo de serviço, Manutenção › Listas; padrão o da manutenção, senão revisao), descricao (o que foi feito, até 4000), mao_de_obra (R$), pecas (uma por linha, "nome; custo", o custo opcional), estanqueidade (o identificador de um resultado, aprovado, reprovado..., ou vazio: não testada; o tipo estanqueidade pede o resultado), estanqueidade_bar (a pressão do teste, só com o resultado), marcha_antes e marcha_depois (s/dia, a que o profissional mediu; + adianta), garantia_ate (AAAA-MM-DD, a partir da data), observacao (texto livre, sem limite), documentos (os ids dos documentos do relógio que são do serviço, separados por vírgula, ou documentos[]): só muda o que vier. O tipo de serviço que marca um tipo de lançamento (o texto do item: revisao, pilha) vira também essa marcação na data do serviço (quando o tipo vale para o relógio): os avisos e as fórmulas de sempre contam o serviço; mudar a data muda a marcação, e mudar o tipo a desfaz'),
                "exemplo" => t('curl -u lucas:senha -d recurso=servicos -d acao=salvar -d relogio_id=3 -d data=2026-10-15 -d tipo=revisao -d oficina_id=2 -d mao_de_obra=300 --data-urlencode "pecas=Coroa; 120,50" -d estanqueidade=aprovado -d estanqueidade_bar=10 http://servidor/relojoeiro/api.php')],
            "excluir" => ["campos" => t('confirmar=1; id (saem as peças e a ligação com os documentos, que ficam no relógio, e a marcação que o serviço criou)'), "exemplo" => t('curl -u lucas:senha -d recurso=servicos -d acao=excluir -d id=4 -d confirmar=1 http://servidor/relojoeiro/api.php')],
        ],
        "manutencao" => [
            "salvar" => ["campos" => t('id (0 ou ausente: uma nova), relogio_id (só na nova: um relógio da coleção, na coleção ou emprestado, sem outra manutenção aberta), oficina_id (uma oficina da coleção), situacao (o identificador de uma situação; sem ela, na nova, a primeira das abertas; mudar por aqui é o mesmo que a ação situacao), tipo (o identificador do tipo de serviço pedido; sem ele, na nova, revisao), problema (até 2000), os (até 60), enviado (AAAA-MM-DD, até hoje; sem ele, hoje), previsao e orcamento_data (AAAA-MM-DD, a partir do envio), orcamento (R$, não negativo), encerrado (AAAA-MM-DD, numa situação que encerra ou cancela; sem ele, o dia da mudança), observacao (até 2000), acessorios (os ids dos acessórios que foram junto, separados por vírgula), documentos (os ids dos documentos do relógio). Só o que vem no pedido muda. Nova e aberta: o relógio fica em manutenção (indisponível até voltar, com a disponibilidade de antes guardada; as sessões abertas dele fecham, e o winder deixa a posição livre; sai do plano de amanhã em diante, sorteado de novo; se era o de hoje, hoje fica livre, ou sem relógio com trocar_hoje desligado; os avisos dele param, menos os da manutenção). Nova numa situação que encerra: o registro de uma manutenção passada, sem mexer no relógio'),
                "exemplo" => t('curl -u lucas:senha -d recurso=manutencao -d acao=salvar -d relogio_id=3 -d oficina_id=2 -d tipo=revisao --data-urlencode "problema=Atrasando 30 s/dia" -d previsao=2026-11-10 http://servidor/relojoeiro/api.php')],
            "situacao" => ["campos" => t('id, situacao (o identificador), quando (AAAA-MM-DD HH:MM, do envio até agora; sem ele, agora), observacao (até 500), encerrado: a mudança fica na história. Numa situação que encerra (Retirado), o relógio volta com a disponibilidade guardada e a manutenção vira um serviço (o tipo, o orçamento como mão de obra e os documentos dela; servico_id na resposta); numa que cancela, volta sem serviço; voltar a uma aberta põe o relógio de novo em manutenção, se ela não tem serviço e ele não está noutra'),
                "exemplo" => t('curl -u lucas:senha -d recurso=manutencao -d acao=situacao -d id=5 -d situacao=retirado http://servidor/relojoeiro/api.php')],
            "excluir" => ["campos" => t('confirmar=1; id (saem a história, os serviços dela, com a marcação de cada um, e as ligações; aberta, o relógio volta antes)'),
                "exemplo" => t('curl -u lucas:senha -d recurso=manutencao -d acao=excluir -d id=5 -d confirmar=1 http://servidor/relojoeiro/api.php')],
        ],
        "oficinas" => [
            "salvar" => ["campos" => t('id (0 ou ausente: uma nova), nome (até 120, sem repetir na coleção), tipo (o identificador de um tipo de oficina; sem ele, na nova, relojoeiro), endereco (até 200), numero (20), complemento (80), bairro (80), cidade (80), uf (40), cep (20), horario (200), observacao (2000), contatos: a lista inteira (os de antes saem; até 30), cada um com tipo (o identificador de um tipo de contato), valor (até 200), pessoa (até 120), observacao (até 200) e principal (1: só o primeiro marcado vale), em contatos[0][tipo]=... ou num JSON; a linha sem valor, pessoa e observação não grava. Só o que vem no pedido muda'),
                "exemplo" => t('curl -u lucas:senha -d recurso=oficinas -d acao=salvar -d "nome=Relojoaria Central" -d tipo=relojoeiro -d "contatos[0][tipo]=whatsapp" -d "contatos[0][valor]=+55 41 99999-0000" -d "contatos[0][principal]=1" http://servidor/relojoeiro/api.php')],
            "excluir" => ["campos" => t('confirmar=1; id (só a oficina sem manutenções: com elas, ela fica, é a história delas; a sua, Eu mesmo (em casa), também fica)'),
                "exemplo" => t('curl -u lucas:senha -d recurso=oficinas -d acao=excluir -d id=4 -d confirmar=1 http://servidor/relojoeiro/api.php')],
        ],
        "listas" => [
            "salvar" => ["campos" => t('id (0 ou ausente: um item novo), lista (só no novo: relogio_situacao, acessorio_tipo, reserva_protocolo, reserva_observacao, manutencao_situacao, servico_tipo, estanqueidade, oficina_tipo ou contato_tipo), identificador (só no novo: minúsculas, números e _, começando por letra, até 20, sem repetir e fora dos reservados; não muda depois), nome (até 80), ordem, comportamento (o que ele faz, nas listas que têm: obrigatório nelas; não muda com o item em uso), texto (nas listas que têm, até 200; no tipo de serviço, o identificador de um tipo de lançamento instantâneo), cor (nas listas que têm: #rrggbb ou vazio). Só o que vem no pedido muda'),
                "exemplo" => t('curl -u lucas:senha -d recurso=listas -d acao=salvar -d lista=manutencao_situacao -d identificador=garantia -d "nome=Na garantia" -d comportamento=aberta -d "texto=Cobrar a garantia" -d cor=#7a4fb5 http://servidor/relojoeiro/api.php')],
            "excluir" => ["campos" => t('confirmar=1; id (só o item fora de uso; e a lista nunca fica sem o que o sistema precisa: a situação na coleção, um que faz colecao; a manutenção, um que faz aberta e um que faz encerra; a oficina, um que faz propria)'),
                "exemplo" => t('curl -u lucas:senha -d recurso=listas -d acao=excluir -d id=40 -d confirmar=1 http://servidor/relojoeiro/api.php')],
        ],
        "timegrapher" => [
            "salvar" => ["campos" => t('id (0 ou sem: uma medição nova), relogio_id (só na nova), quando (AAAA-MM-DD HH:MM; vazio: agora; nunca no futuro), posicao (mostrador_cima, mostrador_baixo, coroa_cima, coroa_baixo, coroa_esquerda, coroa_direita; vazio: não informada), marcha (s/dia, de -999 a 999), amplitude (graus, de 0 a 360), erro_batida (ms, de 0 a 99), bph (de 3600 a 72000), angulo (o ângulo de levantamento, de 10 a 90), observacao (até 500): pelo menos a marcha, a amplitude ou o erro de batida. Os números com ponto ou vírgula. Na que existe, só muda o que vier'),
                "exemplo" => t('curl -u lucas:senha -d recurso=timegrapher -d acao=salvar -d relogio_id=3 -d posicao=mostrador_cima -d marcha=4.5 -d amplitude=290 -d erro_batida=0.3 -d bph=21600 http://servidor/relojoeiro/api.php')],
            "importar" => ["campos" => t('relogio_id, csv (o texto do arquivo) ou arquivo_base64, quando (o instante das linhas sem data; vazio: agora), conferir=1 (só mostra o que entraria, sem gravar): as medições do CSV do aparelho. O separador (; , ou tabulação) vem do cabeçalho, e as colunas pelos nomes, em português ou em inglês (sem acento e sem o que está entre parênteses: date, time, position, rate, amplitude, beat error, bph, lift angle, notes...; a lista inteira em recurso=timegrapher, csv.colunas); as posições pelos códigos, pelo português ou pelas siglas (DU, DD, CU, CD, CL, CR; 3U, 9U, 6U, 12U). A data: AAAA-MM-DD ou DD/MM/AAAA, com a hora ou sem (meio-dia). A linha que não se entende fica de fora com o motivo; a repetida (o mesmo instante, a mesma posição e os mesmos números) também. Até 2000 linhas e 2 MB. A resposta traz importacao: conferir, colunas (o campo e o nome que ele tinha no arquivo), lidas, entram, repetidas, recusadas e linhas[] (linha, estado: entra, repetida ou recusada, os campos lidos e o erro)'),
                "exemplo" => t('curl -u lucas:senha -d recurso=timegrapher -d acao=importar -d relogio_id=3 --data-urlencode csv@medicoes.csv -d conferir=1 http://servidor/relojoeiro/api.php')],
            "excluir" => ["campos" => t('id, confirmar=1 (sem ele, a API diz o que sai e não apaga): sai a medição'),
                "exemplo" => t('curl -u lucas:senha -d recurso=timegrapher -d acao=excluir -d id=7 -d confirmar=1 http://servidor/relojoeiro/api.php')],
        ],
        "reserva" => [
            "iniciar" => ["campos" => t('relogio_id (um relógio com a reserva de marcha no cadastro: o mecânico), inicio (quando ele ficou cheio: AAAA-MM-DD HH:MM; vazio: agora; nunca no futuro), protocolo (como encheu: o identificador de um jeito de carregar, Cadastros › Listas: corda, winder, pulso, outro...; padrão outro), protocolo_valor (as voltas da coroa, ou as horas no winder ou no pulso), observacao (até 500): começa um teste da reserva; um em andamento por relógio. Depois, deixe ele parado, sem corda nem pulso, e marque quando ele parar'),
                "exemplo" => t('curl -u lucas:senha -d recurso=reserva -d acao=iniciar -d relogio_id=3 -d "inicio=2026-10-15 08:00" -d protocolo=corda -d protocolo_valor=40 http://servidor/relojoeiro/api.php')],
            "parou" => ["campos" => t('id (o teste), ou relogio_id (o teste em andamento dele), fim (quando ele parou, depois do inicio; vazio: agora), observacao: termina o teste; as horas de cheio até parado são a reserva medida, e a mediana dos testes, a estimativa do relógio'),
                "exemplo" => t('curl -u lucas:senha -d recurso=reserva -d acao=parou -d relogio_id=3 -d "fim=2026-10-17 02:00" http://servidor/relojoeiro/api.php')],
            "observar" => ["campos" => t('relogio_id (o mecânico ou o solar), tipo (o identificador de uma observação, Cadastros › Listas: parou, carga_baixa, nota...; padrão nota), quando (vazio: agora), observacao (a nota pede o texto): uma observação da energia. No solar não há teste nem calibração: a recarga depende da luz, que o sistema não mede'),
                "exemplo" => t('curl -u lucas:senha -d recurso=reserva -d acao=observar -d relogio_id=5 -d tipo=carga_baixa http://servidor/relojoeiro/api.php')],
            "salvar" => ["campos" => t('id; no teste: inicio, fim (vazio: em andamento), protocolo, protocolo_valor, observacao; na observação: tipo, quando, observacao. Só muda o que vier'),
                "exemplo" => t('curl -u lucas:senha -d recurso=reserva -d acao=salvar -d id=4 -d "fim=2026-10-17 03:00" http://servidor/relojoeiro/api.php')],
            "usar" => ["campos" => t('relogio_id: a mediana dos testes, em horas inteiras, vira a reserva de marcha do cadastro do próprio relógio (a que vale na conta); o calibre e o padrão do grupo não mudam, e apagar o valor do relógio no cadastro volta a eles'),
                "exemplo" => t('curl -u lucas:senha -d recurso=reserva -d acao=usar -d relogio_id=3 http://servidor/relojoeiro/api.php')],
            "excluir" => ["campos" => t('confirmar=1; id (o teste ou a observação)'), "exemplo" => t('curl -u lucas:senha -d recurso=reserva -d acao=excluir -d id=4 -d confirmar=1 http://servidor/relojoeiro/api.php')],
        ],
        "documento_categorias" => [
            "nova" => ["campos" => t('identificador, nome, aceita[] (imagem, video, audio, pdf, xml; nenhum: qualquer arquivo), ordem (vazio: no fim)'), "exemplo" => t('curl -u lucas:senha -d recurso=documento_categorias -d acao=nova -d identificador=garantia -d nome=Garantia -d "aceita[]=pdf" http://servidor/relojoeiro/api.php')],
            "alterar" => ["campos" => t('id, nome, aceita[], ordem (o identificador não muda)'), "exemplo" => t('curl -u lucas:senha -d recurso=documento_categorias -d acao=alterar -d id=7 -d nome=Garantias http://servidor/relojoeiro/api.php')],
            "excluir" => ["campos" => t('confirmar=1; id (só uma categoria sem documentos)'), "exemplo" => t('curl -u lucas:senha -d recurso=documento_categorias -d acao=excluir -d id=7 -d confirmar=1 http://servidor/relojoeiro/api.php')],
        ],
        "lancamento" => [
            "lancar" => ["campos" => t('relogio_id, tipo (instantâneo ou com valor), valor (com valor), quando (AAAA-MM-DD HH:MM; vazio: agora), medir (1, o padrão, ou 0: num tipo que mede o gasto, com 1 a medição entra na média; com 0 fica só no histórico), estado (uso ou repouso; vazio: não diz): a marcação da leitura, que fica gravada nela e manda (o gasto em uso sai só das leituras marcadas em uso; o em repouso, só das em repouso); se o pulso registrado no instante da leitura não bate com ela, a resposta vem com confirmar: true e a pergunta, e o lançamento só grava de novo com confirmar=1 (vale o que a pessoa marcou). No tipo que mede a marcha com desvio (o Desvio da hora): valor é o desvio em segundos (+ adiantado, − atrasado; até 6 horas), ou marca (a hora que o relógio mostra, HH:MM:SS, comparada com a hora certa do servidor no instante da leitura: instante_ms, em milissegundos, de até 10 minutos atrás; sem ele, agora; o mostrador dá a volta em 12 horas); posicao: onde ele ficou desde a leitura anterior (misto, pulso, mostrador_cima, mostrador_baixo, coroa_cima, coroa_baixo, coroa_esquerda, coroa_direita, winder; vazio: não informada). A mensagem diz a marcha desde a leitura anterior. O tipo que mede a marcha com acerto (o Acerto da hora): o relógio volta a 0 s, e a conta da marcha recomeça dele'), "exemplo" => t('curl -u lucas:senha -d recurso=lancamento -d acao=lancar -d relogio_id=10 -d tipo=carga -d valor=68 http://servidor/relojoeiro/api.php')],
            "iniciar" => ["campos" => t('relogio_id, tipo (sessão), quando: abre a sessão; uma exclusiva fecha a outra exclusiva aberta. O winder é obrigatório: num tipo marcado como winder, recusa sempre (sem winder cadastrado, não há pôr no winder; com winder, o relógio vai para ele pela página Winders: recurso=winder_posicoes, acao=salvar, com o relogio_id, que abre a sessão na posição), a não ser que ele tenha o lugar dele (o lugar fixo) ligado e livre: aí volta para lá, e a mensagem diz onde; com o lugar desligado ou com outro relógio, recusa e diz por quê)'), "exemplo" => t('curl -u lucas:senha -d recurso=lancamento -d acao=iniciar -d relogio_id=4 -d tipo=sol http://servidor/relojoeiro/api.php')],
            "encerrar" => ["campos" => t('relogio_id, tipo, quando: fecha a sessão aberta (o tirar do winder também: daqui, do atalho ou da página Winders)'), "exemplo" => t('curl -u lucas:senha -d recurso=lancamento -d acao=encerrar -d relogio_id=4 -d tipo=sol http://servidor/relojoeiro/api.php')],
            "periodo" => ["campos" => t('relogio_id, tipo, inicio (quando também vale), fim: uma sessão que já passou (espaço ou T entre data e hora); no pulso do relógio do dia, é uso do rodízio, como o iniciar; os trechos do mesmo tipo que ela cobre ou em que encosta (o iniciar aberto depois dela, por exemplo) viram um só, do primeiro início ao último fim (aberto, se um deles está aberto); num tipo marcado como winder, só com winder cadastrado e com posicao_id, a posição onde ele esteve (recurso=winders; sem outro relógio nela nesse tempo); o programa dela entra nas fórmulas por WINDER_POSICAO'), "exemplo" => t('curl -u lucas:senha -d recurso=lancamento -d acao=periodo -d relogio_id=3 -d tipo=winder -d posicao_id=7 -d "inicio=2026-09-26 20:00" -d "fim=2026-09-27 07:00" http://servidor/relojoeiro/api.php')],
            "alterar" => ["campos" => t('id: quando ou inicio e fim, valor, estado (a marcação da leitura: uso, repouso ou vazio; só o que vier), posicao (a da leitura do desvio da hora; vazio: não informada; só se vier), posicao_id (a posição do winder da sessão; 0: nenhuma; só se vier)'), "exemplo" => t('curl -u lucas:senha -d recurso=lancamento -d acao=alterar -d id=42 -d valor=70 http://servidor/relojoeiro/api.php')],
            "excluir" => ["campos" => t('confirmar=1; id'), "exemplo" => t('curl -u lucas:senha -d recurso=lancamento -d acao=excluir -d id=42 -d confirmar=1 http://servidor/relojoeiro/api.php')],
            "medicao" => ["campos" => t('id (a medição do gasto, de medicoes[] na ficha), usada (1: entra na conta; 0: fica só no histórico): pôr ou tirar uma medição da conta do gasto, sem apagar nada'), "exemplo" => t('curl -u lucas:senha -d recurso=lancamento -d acao=medicao -d id=13 -d usada=0 http://servidor/relojoeiro/api.php')],
            "alternar" => ["campos" => t('relogio_id, tipo (sessão), quando: fecha a sessão se ela está aberta, abre se está fechada (um botão só num atalho de celular); no tipo marcado como winder, abrir é como o iniciar (volta para o lugar dele, se está livre; sem lugar, recusa). Em todas as ações, relogio_id=hoje é o relógio do dia, pelo plano'), "exemplo" => t('curl -H "X-Api-Token: ..." -d recurso=lancamento -d acao=alternar -d relogio_id=hoje -d tipo=pulso http://servidor/relojoeiro/api.php')],
        ],
        "avisos" => [
            "novo" => ["campos" => t('identificador, nome, expressao (a data prevista), condicao (vale quando: uma fórmula, 1 vale e 0 não; vazia, vale sempre; ex.: corda_manual = 0), antecedencia_dias, texto (o motivo, com {relogio}, {data}, {quando}, {limite}), resolve (o tipo de lançamento), ativo, no_id, escala (nao, uso, sempre), simula_valor, simula_horas, agenda (janela ou sempre), na_hora (1 ou 0: o Telegram recebe o aviso no minuto em que ele vence, uma vez)'), "exemplo" => t('curl -u lucas:senha -d recurso=avisos -d acao=novo -d identificador=pulseira -d "nome=Trocar a pulseira" --data-urlencode "expressao=data_compra + 365" -d antecedencia_dias=15 -d "texto=vence {quando}, {data}" -d no_id=0 http://servidor/relojoeiro/api.php')],
            "alterar" => ["campos" => t('id e os mesmos campos (menos o identificador)'), "exemplo" => t('curl -u lucas:senha -d recurso=avisos -d acao=alterar -d id=9 -d antecedencia_dias=30 http://servidor/relojoeiro/api.php')],
            "excluir" => ["campos" => t('confirmar=1; id (a versão)'), "exemplo" => t('curl -u lucas:senha -d recurso=avisos -d acao=excluir -d id=9 -d confirmar=1 http://servidor/relojoeiro/api.php')],
        ],
        "criterios" => [
            "conjunto_criar" => ["campos" => t('escopo ("" todos, g:<grupo>, r:<relógio>), origem (herdado: copia o que ele usa hoje; vazio)'), "exemplo" => t('curl -u lucas:senha -d recurso=criterios -d acao=conjunto_criar -d escopo=r:10 -d origem=herdado http://servidor/relojoeiro/api.php')],
            "conjunto_excluir" => ["campos" => t('escopo (volta a herdar o de cima)'), "exemplo" => t('curl -u lucas:senha -d recurso=criterios -d acao=conjunto_excluir -d escopo=r:10 http://servidor/relojoeiro/api.php')],
            "param_novo" => ["campos" => t('escopo, nome, peso (os outros abrem espaço na proporção)'), "exemplo" => t('curl -u lucas:senha -d recurso=criterios -d acao=param_novo -d escopo=g:1 -d "nome=Estilo" -d peso=10 http://servidor/relojoeiro/api.php')],
            "param_pesos" => ["campos" => t('escopo, nome[<id>], peso[<id>]: todos os do conjunto, somando 100'), "exemplo" => t('curl -u lucas:senha -d recurso=criterios -d acao=param_pesos -d escopo=g:1 -d "peso[5]=35" -d "peso[6]=10" http://servidor/relojoeiro/api.php')],
            "param_excluir" => ["campos" => t('id (o peso dele vai para os outros na proporção)'), "exemplo" => t('curl -u lucas:senha -d recurso=criterios -d acao=param_excluir -d id=29 http://servidor/relojoeiro/api.php')],
            "sub_novo" => ["campos" => t('parametro_id, nome, variavel (o identificador de um campo ou fórmula; metrica também vale), peso'), "exemplo" => t('curl -u lucas:senha -d recurso=criterios -d acao=sub_novo -d parametro_id=5 -d "nome=Carga" -d variavel=energia -d peso=20 http://servidor/relojoeiro/api.php')],
            "sub_pesos" => ["campos" => t('parametro_id, nome[<id>], peso[<id>]: somando 100'), "exemplo" => t('curl -u lucas:senha -d recurso=criterios -d acao=sub_pesos -d parametro_id=5 -d "peso[6]=60" -d "peso[7]=40" http://servidor/relojoeiro/api.php')],
            "sub_excluir" => ["campos" => "id", "exemplo" => t('curl -u lucas:senha -d recurso=criterios -d acao=sub_excluir -d id=7 http://servidor/relojoeiro/api.php')],
            "sub_medida" => ["campos" => t('id, variavel (metrica também vale; as faixas recomeçam)'), "exemplo" => t('curl -u lucas:senha -d recurso=criterios -d acao=sub_medida -d id=7 -d variavel=dias_de_carga http://servidor/relojoeiro/api.php')],
            "sub_mover" => ["campos" => t('id, parametro_id (o de destino, de qualquer lugar)'), "exemplo" => t('curl -u lucas:senha -d recurso=criterios -d acao=sub_mover -d id=7 -d parametro_id=8 http://servidor/relojoeiro/api.php')],
            "ordem" => ["campos" => t('tipo (parametro ou sub), id, direcao (sobe ou desce)'), "exemplo" => t('curl -u lucas:senha -d recurso=criterios -d acao=ordem -d tipo=parametro -d id=5 -d direcao=desce http://servidor/relojoeiro/api.php')],
            "faixas" => ["campos" => t('sub_id, de[], ate[], categoria[], nota[], apagar[] (todas as faixas do subparâmetro de uma vez; a última vai até o limite da medida ou sem limite)'), "exemplo" => t('curl -u lucas:senha -d recurso=criterios -d acao=faixas -d sub_id=6 -d "de[0]=0" -d "ate[0]=50" -d "nota[0]=30" -d "de[1]=50" -d "ate[1]=100" -d "nota[1]=100" http://servidor/relojoeiro/api.php')],
            "restaurar" => ["campos" => t('(nada): volta aos critérios iniciais'), "exemplo" => t('curl -u lucas:senha -d recurso=criterios -d acao=restaurar http://servidor/relojoeiro/api.php')],
        ],
        "rodizio" => [
            "modo" => ["campos" => t('modo (o id), selecao (o critério de escolha; só nos tipos semana, semana_fds e dia_semana), max_sem_uso (a garantia de rodízio, da coleção): grava os dois e marca o modo para os próximos sorteios; o plano gravado continua (rodizio resortear o refaz), menos o que foi sorteado depois do fim das semanas do modo novo, que sai na próxima montagem. Os blocos, as semanas e o roteiro se editam em recurso=modos'), "exemplo" => t('curl -u lucas:senha -d recurso=rodizio -d acao=modo -d modo=2 -d selecao=ponderado -d max_sem_uso=21 http://servidor/relojoeiro/api.php')],
            "resortear" => ["campos" => t('(nada): refaz o plano de amanhã até o fim da semana (o último dia dela, pela Configuração semana_inicio; até o fim da próxima semana, se ela foi montada pela proxima_semana; o que outro modo sorteou depois disso, como a escala, sai e não volta; na escala, até o fim da escala); se o dia ainda não começou no pulso e a Configuração deixa trocar o relógio de hoje no próprio dia (trocar_hoje=1), também hoje; os dias escolhidos à mão e os livres ficam (a mensagem diz quantos); sobrescrever=1 (a caixa Sobrescrever tudo): sai tudo o que o plano tem do começo do sorteio em diante, à mão, livre ou sorteado, e o modo monta de novo (a mensagem diz quantos foram sobrescritos)'), "exemplo" => t('curl -u lucas:senha -d recurso=rodizio -d acao=resortear http://servidor/relojoeiro/api.php')],
            "resortear_hoje" => ["campos" => t('(nada): inclusive hoje; se sair outro relógio, ele passa a ser o do pulso a partir de agora; sobrescrever=1: como no resortear, sai tudo de hoje em diante'), "exemplo" => t('curl -u lucas:senha -d recurso=rodizio -d acao=resortear_hoje http://servidor/relojoeiro/api.php')],
            "sem_relogio" => ["campos" => t('(nada): hoje sem relógio: o dia fica livre (sem relógio e sem sorteio) e a sessão do rodízio de hoje termina agora (o tempo que já ficou no pulso conta; a que nem começou sai); nenhum relógio vai ao pulso sozinho hoje; os outros dias não mudam. Desfaz: trocar_dia de hoje (ou usando) com um relógio, ou resortear_hoje'), "exemplo" => t('curl -u lucas:senha -d recurso=rodizio -d acao=sem_relogio http://servidor/relojoeiro/api.php')],
            "usando" => ["campos" => t('relogio_id: o relógio de hoje, a partir de agora (na escala, fica os dias que faltavam do bloco de hoje); motivo (opcional): a frase que fica no plano no lugar de "Escolhido à mão: você marcou que está usando este hoje."'), "exemplo" => t('curl -u lucas:senha -d recurso=rodizio -d acao=usando -d relogio_id=12 http://servidor/relojoeiro/api.php')],
            "trocar_dia" => ["campos" => t('data (AAAA-MM-DD, de hoje em diante), relogio_id: o relógio daquele dia, escolhido à mão (hoje: como o usando; na escala, só esse dia muda: os outros ficam com o relógio que têm, e só o que fazer deles é refeito); relogio_id 0: o dia volta a ser sorteado; relogio_id sortear:<forma> (inteligente, ponderado, aleatorio ou fifo): o dia é sorteado agora por essa forma de escolha, entre os disponíveis do bloco do modo ativo que cobre o dia (sem bloco: todos), sem o que o dia tinha, com a garantia de rodízio na frente (menos no aleatório) e os dias anteriores do plano contados como uso; fica à mão, com o motivo "Sorteado à mão (<forma>): ..."; hoje, como o usando'), "exemplo" => t('curl -u lucas:senha -d recurso=rodizio -d acao=trocar_dia -d data=2026-10-09 -d relogio_id=12 http://servidor/relojoeiro/api.php')],
            "periodo" => ["campos" => t('de, ate (AAAA-MM-DD, de hoje até 2 anos), relogio_ids[] (um ou vários, na ordem), dias_cada (padrão 1): os dias do período ficam escolhidos à mão, cada relógio dias_cada dias seguidos, e depois do último volta ao primeiro (hoje: o primeiro passa a ser o do pulso a partir de agora; na escala, só o período muda: fora dele, cada dia fica com o relógio que tem)'), "exemplo" => t('curl -u lucas:senha -d recurso=rodizio -d acao=periodo -d de=2026-12-20 -d ate=2027-01-05 -d "relogio_ids[]=12" -d "relogio_ids[]=7" -d dias_cada=2 http://servidor/relojoeiro/api.php')],
            "periodo_sortear" => ["campos" => t('de, ate (um dos dois pode faltar: sem o de, de amanhã; sem o ate, até o último dia do plano): os dias do período, de amanhã em diante (à mão, sorteados ou livres), saem do plano e o modo de rodízio monta esses dias de novo, só eles (na escala também: fora do período, cada dia fica com o relógio que tem); os dias escolhidos à mão e os livres ficam quando se sorteia de novo ou se monta a próxima semana'), "exemplo" => t('curl -u lucas:senha -d recurso=rodizio -d acao=periodo_sortear -d de=2026-12-20 -d ate=2027-01-05 http://servidor/relojoeiro/api.php')],
            "apagar_tudo" => ["campos" => t('hoje (1: Excluindo hoje, de hoje em diante; sem ele, de amanhã em diante): toda a programação (os dias escolhidos à mão, os sorteados, os livres e a próxima semana montada) sai e o modo ativo monta o plano de novo; hoje, se mudar, o novo vai para o pulso a partir de agora'), "exemplo" => t('curl -u lucas:senha -d recurso=rodizio -d acao=apagar_tudo -d hoje=1 http://servidor/relojoeiro/api.php')],
            "manual" => ["campos" => t('de, ate; dias[AAAA-MM-DD]: o id do relógio, auto (Decida por mim: o sistema decide ao gravar, pelo critério do recurso=rodizio_manual), sortear:<forma> (o dia sorteado ao gravar por essa forma de escolha: inteligente, ponderado, aleatorio ou fifo; sem o de ontem e o de amanhã, como o Decida por mim) ou livre (hoje não). O dia que não vem fica com a escolha de partida (dias[].escolha do recurso=rodizio_manual). Tudo fica gravado à mão, com o motivo; hoje, com outro relógio, ele passa a ser o do pulso a partir de agora; hoje em auto continua o que está. Fora do período, vale o modo ativo, e nada muda (na escala também)'), "exemplo" => t('curl -u lucas:senha -d recurso=rodizio -d acao=manual -d de=2026-12-20 -d ate=2027-01-05 -d "dias[2026-12-20]=12" -d "dias[2026-12-21]=auto" -d "dias[2026-12-25]=livre" http://servidor/relojoeiro/api.php')],
            "periodo_livre" => ["campos" => t('de, ate (como no periodo_sortear: um dos dois pode faltar): tudo o que o período tem, de amanhã em diante, sai e os dias ficam livres: sem relógio e sem sorteio (nem a escala), para escolher à mão (trocar_dia ou periodo num dia livre o tira de lá)'), "exemplo" => t('curl -u lucas:senha -d recurso=rodizio -d acao=periodo_livre -d de=2026-12-20 -d ate=2027-01-05 http://servidor/relojoeiro/api.php')],
            "proxima_semana" => ["campos" => t('(nada): em qualquer dia, monta ou refaz a semana seguinte inteira (do primeiro ao último dia, de segunda a domingo ou de domingo a sábado, pela Configuração semana_inicio; no último dia da semana, a que começa amanhã), com os dias que ainda faltam desta semana já contados como uso (a simulação no pulso); os dias escolhidos à mão ficam; sobrescrever=1: sai tudo do primeiro dia dela em diante (à mão, livre ou sorteado) antes de montar; recusada na escala'), "exemplo" => t('curl -u lucas:senha -d recurso=rodizio -d acao=proxima_semana http://servidor/relojoeiro/api.php')],
        ],
        "modos" => [
            "salvar" => ["campos" => t('id (0 cria), nome, tipo (semana, semana_fds, dia_semana, aleatorio, escala ou personalizado; sem ele, inferido dos blocos), selecao (inteligente, ponderado, aleatorio, fifo; o aleatório força aleatorio; a escala e o personalizado não a usam), escala_dias (só na escala: 7 a 730), semanas (1 a 8: quantas semanas à frente o plano vem montado; não na escala), blocos[n][nome], blocos[n][dias][], blocos[n][no_id], blocos[n][um_por] (dia ou bloco), blocos[n][relogio_id] (0: sorteia); substitui os blocos (a forma deles pelo tipo: semana e aleatorio, um bloco com os sete dias; semana_fds, segunda a sexta e sábado e domingo; dia_semana, um por dia); roteiro (o personalizado: as linhas "nome = expressão", conferidas como no recurso=roteiro; os outros tipos geram o roteiro dos blocos); ciclo (1 ou 0, o padrão: com o ciclo, um relógio só volta depois que todos os candidatos passaram na semana)'), "exemplo" => t('curl -u lucas:senha -d recurso=modos -d acao=salvar -d id=0 -d "nome=Só smartwatch" -d selecao=inteligente -d "blocos[0][nome]=Todo dia" -d "blocos[0][dias][]=1" -d "blocos[0][dias][]=7" -d "blocos[0][no_id]=1" -d "blocos[0][um_por]=dia" http://servidor/relojoeiro/api.php')],
            "ativar" => ["campos" => t('id (só marca o modo: o plano gravado continua, e o modo vale para os próximos sorteios; para refazer o plano, rodizio resortear ou periodo_sortear)'), "exemplo" => t('curl -u lucas:senha -d recurso=modos -d acao=ativar -d id=5 http://servidor/relojoeiro/api.php')],
            "excluir" => ["campos" => t('confirmar=1; id (não o ativo)'), "exemplo" => t('curl -u lucas:senha -d recurso=modos -d acao=excluir -d id=6 -d confirmar=1 http://servidor/relojoeiro/api.php')],
        ],
        "config" => [
            "salvar" => ["campos" => t('horario_manha, horario_noite, uso_inicio, uso_fim, sol_fim (HH:MM), pulso_auto_inicio, pulso_auto_fim e sol_auto_fim (1 ou 0), senha_tamanho (4 a 128), senha_maiusculas, senha_minusculas, senha_numeros e senha_simbolos (0 a 32: a força da senha, só o master), carga_limiar (1 a 99), sol_limiar (1 a 99), painel_modo (lado: o relógio abre no painel ao lado da lista; flutuante: numa janela grande por cima da página), destaque_hoje (dia: o destaque no alto da página Hoje é o relógio do dia; pulso: o relógio no pulso agora), idioma (pt-BR, en, zh-CN, hi, es ou fr: o idioma padrão da coleção: o das mensagens e das agendas sem idioma próprio), proximos_por_pagina e plano_por_pagina (1 a 366: o Mostrar até dos Próximos dias da página Hoje e do dia a dia da página Plano; padrão 7 e 31), atualizar_segundos (0 a 86400: de quantos em quantos segundos as páginas se atualizam sozinhas; 0 desliga; vazio: 60), relojinho_modo (hora, aleatorio ou sem_repeticao: o reloginho da barra e da aba, um dos 24 modelos por hora: o da hora, um sorteado a cada hora (pode repetir) ou os 24 embaralhados, cada um uma vez por dia; vazio: hora), max_sem_uso, previsao_limite, gasto_motor (vazio, horas, robusto, marcacao, cadastro ou formulas: como calcular o gasto da bateria, para todos os relógios da coleção; vazio: o do relógio e o do grupo), medicao_base (dias ou leituras: o que o gasto medido conta), medicao_janela_dias (1 a 3650: a janela da conta do gasto medido, com contar por dias), medicao_janela_leituras (2 a 1000: as últimas leituras de cada tipo, com contar por leituras), documentos_copia (vazio, todos ou nenhum: a cópia dos documentos no banco, para a coleção inteira), encostado_ativo (1 ou 0: liga ou desliga o aviso Encostado inteiro, o aviso do cadastro), encostado_dias (1 a 3650: o aviso Encostado, dias sem ir ao pulso), fuso (o fuso horário da coleção, um nome que o PHP conheça, como America/Sao_Paulo ou Europe/Lisbon: o de quem não escolheu o seu em Minha conta, e o do cron, das mensagens e das agendas; vazio: o do sistema), hora_relogio (o relógio da página Hora certa: analogico, digital, anadigi (o visor digital dentro do analógico) ou ambos (um ao lado do outro); vazio: ambos), semana_inicio (segunda ou domingo: o primeiro dia da semana do rodízio: o plano vem montado até o último dia da semana, e o ciclo, a próxima semana e o relógio para a semana inteira contam dela; vazio: segunda), escala_inicio (amanha ou hoje: de onde a escala inteligente conta os dias do modo: amanha, hoje ou, se o dia de hoje já começou no pulso, amanhã; hoje, sempre hoje, que conta como o 1º dia; mudou: o escala_fim sai e a próxima montagem refaz a escala; vazio: amanha), escala_periodo (corridos, semana ou mes: onde a escala inteligente fecha: nos dias corridos do período, no fim da semana, semanas inteiras, ou no fim do mês, meses inteiros; mudou: o escala_fim sai; vazio: corridos), semana_ultimo_dia (dia_seguinte ou semana_seguinte: no último dia da semana, os modos por semana montam só o dia seguinte ou a semana seguinte inteira; vazio: dia_seguinte), trocar_hoje (1 ou 0: o relógio de hoje se troca no próprio dia, ou só a partir de amanhã; vazio: 0), calibre_campos (movimento ou todos: os campos do formulário do calibre; vazio: movimento), url_sistema (o endereço do sistema, para os links das mensagens, do ICS e do Outlook: do sistema inteiro, só o master); só o que vier muda. As mensagens e as agendas têm os recursos delas: destinos e agendas'), "exemplo" => t('curl -u lucas:senha -d recurso=config -d acao=salvar -d horario_manha=06:30 -d carga_limiar=25 http://servidor/relojoeiro/api.php')],
            "evento_salvar" => ["campos" => t('evento_id (ou id; 0 cria), nome, ativo, repeticao (uma, diaria, semanal, mensal, intervalo), hora (HH:MM), data_inicio, dias_semana (1 a 7), dia_mes, intervalo_dias, relogio_id; o evento novo já vai para todos os destinos da coleção'), "exemplo" => t('curl -u lucas:senha -d recurso=config -d acao=evento_salvar -d evento_id=0 -d "nome=Limpar as pulseiras" -d repeticao=semanal -d "dias_semana[]=1" -d "dias_semana[]=4" -d hora=20:00 http://servidor/relojoeiro/api.php')],
            "evento_excluir" => ["campos" => t('evento_id (ou id), confirmar=1'), "exemplo" => t('curl -u lucas:senha -d recurso=config -d acao=evento_excluir -d evento_id=3 -d confirmar=1 http://servidor/relojoeiro/api.php')],
        ],
        "destinos" => [
            "salvar" => ["campos" => t('id (0 cria), tipo (webhook, email ou webpush; só ao criar), nome, ativo (1 ou 0), idioma (vazio: o da coleção), fuso (o fuso das horas no texto das mensagens dele, um nome que o PHP conheça; vazio: o da coleção), modelo (a mensagem padrão, com as âncoras), envia[] (os tipos que ele recebe: dia, vespera, os identificadores dos avisos, ev<id> dos eventos), modelo_<tipo> (o texto próprio de um tipo; vazio: a mensagem padrão); webhook: metodo (GET, POST ou PUT), url, formato (query, form ou json), campo_nome[] e campo_valor[] (cada valor com {titulo} e {mensagem}), corpo_json (opcional), cabecalho_nome[] e cabecalho_valor[] (guardados cifrados; vazio mantém o guardado); email: para (um ou mais, separados por vírgula); webpush: usuario_id (alguém que vê a coleção: vai para os aparelhos dele). Fora das coleções do master, o endereço do webhook tem de ser da internet (nada da rede interna do servidor)'), "exemplo" => t('curl -u lucas:senha -d recurso=destinos -d acao=salvar -d id=0 -d tipo=webhook -d "nome=Telegram" -d metodo=GET --data-urlencode "url=https://api.telegram.org/bot<token>/sendMessage" -d formato=query -d "campo_nome[]=chat_id" -d "campo_valor[]=123" -d "campo_nome[]=text" --data-urlencode "campo_valor[]={mensagem}" http://servidor/relojoeiro/api.php')],
            "testar" => ["campos" => t('id, qual (texto: uma mensagem de teste; manha ou noite: a mensagem de hoje desse horário, como ela sai por ele)'), "exemplo" => t('curl -u lucas:senha -d recurso=destinos -d acao=testar -d id=1 -d qual=manha http://servidor/relojoeiro/api.php')],
            "excluir" => ["campos" => t('id, confirmar=1'), "exemplo" => t('curl -u lucas:senha -d recurso=destinos -d acao=excluir -d id=2 -d confirmar=1 http://servidor/relojoeiro/api.php')],
        ],
        "agendas" => [
            "salvar" => ["campos" => t('id (0 cria), tipo (google, caldav, outlook ou ics; só ao criar), nome, ativa (1 ou 0), janela_dias (1 a 365: quantos dias à frente ficam na agenda), idioma, fuso (o fuso das horas no texto dos eventos; vazio: o da coleção), modelo (o título na primeira linha, a descrição no resto, com as âncoras), envia[] (os tipos que ela recebe); google: calendario_id, chave_json (o JSON da conta de serviço, guardado cifrado; o caminho de um arquivo no servidor, só o master); caldav: url (o endereço do calendário), usuario, senha (no iCloud, uma senha de app; guardada cifrada; vazio mantém); outlook: calendario_id (vazio: o calendário principal), e depois outlook_conectar; ics: nada (o link sai pronto)'), "exemplo" => t('curl -u lucas:senha -d recurso=agendas -d acao=salvar -d id=0 -d tipo=caldav -d "nome=iCloud" --data-urlencode "url=https://caldav.icloud.com/123/calendars/relogios/" -d usuario=eu@icloud.com -d senha=abcd-efgh-ijkl-mnop http://servidor/relojoeiro/api.php')],
            "sincronizar" => ["campos" => t('id: deixa a agenda igual ao que tem de estar nela agora (cria, atualiza e apaga os eventos do sistema); o cron faz sozinho de manhã e à noite'), "exemplo" => t('curl -u lucas:senha -d recurso=agendas -d acao=sincronizar -d id=1 http://servidor/relojoeiro/api.php')],
            "teste_criar" => ["campos" => t('id: cria um evento de teste daqui a 10 minutos'), "exemplo" => t('curl -u lucas:senha -d recurso=agendas -d acao=teste_criar -d id=1 http://servidor/relojoeiro/api.php')],
            "teste_remover" => ["campos" => t('id: remove o evento de teste'), "exemplo" => t('curl -u lucas:senha -d recurso=agendas -d acao=teste_remover -d id=1 http://servidor/relojoeiro/api.php')],
            "novo_link" => ["campos" => t('id (uma agenda ICS): gera outro link; o antigo para de funcionar'), "exemplo" => t('curl -u lucas:senha -d recurso=agendas -d acao=novo_link -d id=3 http://servidor/relojoeiro/api.php')],
            "outlook_conectar" => ["campos" => t('id (uma agenda do Outlook): devolve url, o endereço da Microsoft para entrar na conta e autorizar; a Microsoft volta para recurso=outlook_retorno'), "exemplo" => t('curl -u lucas:senha -d recurso=agendas -d acao=outlook_conectar -d id=4 http://servidor/relojoeiro/api.php')],
            "excluir" => ["campos" => t('id, confirmar=1 (os eventos que o sistema criou nela ficam lá)'), "exemplo" => t('curl -u lucas:senha -d recurso=agendas -d acao=excluir -d id=2 -d confirmar=1 http://servidor/relojoeiro/api.php')],
        ],
        "usuarios" => [
            "salvar" => ["campos" => t('cria a conta (só o master; o primeiro usuário sai pelo token, sem usuários o login não entra, e é o master): login, senha (com a força da Configuração; com senha_confirmacao, as duas iguais), ou login e senha_hash (o hash de outro sistema, bcrypt ou argon2: o usuário entra com a senha de lá; veja senhas); email, idioma, colecao_nova (modelo: uma coleção com o conjunto inicial, o padrão; vazia: uma coleção sem nada; nenhuma: sem coleção). Nunca duas contas com o mesmo: o login que já existe (sem diferenciar maiúscula, sem os espaços das pontas) é recusado, e a conta que existe fica como está (a senha dela muda pela acao=senha); o login também não pode ser o e-mail de outra conta (os dois servem para entrar), nem o e-mail o de outra. A conta criada pelo master é oficial (não vence)'), "exemplo" => t('curl -u lucas:senha -d recurso=usuarios -d acao=salvar -d login=visitante -d senha=segredo123 -d email=visitante@exemplo.com http://servidor/relojoeiro/api.php')],
            "senha" => ["campos" => t('usuario_id ou login; senha (com a força da Configuração) e senha_confirmacao (igual), ou senha_hash (o hash de outro sistema): troca a senha da conta, e os aparelhos lembrados dela são esquecidos. O master troca a de qualquer um; os outros, só a própria (em Minha conta é recurso=conta, acao=alterar, com a senha atual). No servidor, o php senha.php troca sem a força da Configuração'), "exemplo" => t('curl -u lucas:senha -d recurso=usuarios -d acao=senha -d login=visitante -d senha=Nova-senha-1 -d senha_confirmacao=Nova-senha-1 http://servidor/relojoeiro/api.php')],
            "alterar" => ["campos" => t('(só o master) usuario_id ou login; novo_login (nunca o login nem o e-mail de outra conta), email (nunca o e-mail nem o login de outra), idioma, fuso (o fuso horário dele: um nome, navegador ou vazio: o da coleção), papel (master ou comum; sobra sempre um master; o master não vence)'), "exemplo" => t('curl -u lucas:senha -d recurso=usuarios -d acao=alterar -d login=visitante -d email=novo@exemplo.com http://servidor/relojoeiro/api.php')],
            "oficializar" => ["campos" => t('(só o master) usuario_id ou login: a conta de demonstração vira oficial (não vence mais)'), "exemplo" => t('curl -u lucas:senha -d recurso=usuarios -d acao=oficializar -d login=visitante http://servidor/relojoeiro/api.php')],
            "prorrogar" => ["campos" => t('(só o master) usuario_id ou login, dias (1 a 3650): soma os dias ao vencimento (ou a partir de hoje, se já venceu); os avisos de vencimento recomeçam'), "exemplo" => t('curl -u lucas:senha -d recurso=usuarios -d acao=prorrogar -d login=visitante -d dias=30 http://servidor/relojoeiro/api.php')],
            "voltar_demo" => ["campos" => t('(só o master) usuario_id ou login, dias (padrão: DEMO_DIAS): a conta oficial volta a ser de demonstração, vencendo daqui a esses dias'), "exemplo" => t('curl -u lucas:senha -d recurso=usuarios -d acao=voltar_demo -d login=visitante -d dias=15 http://servidor/relojoeiro/api.php')],
            "bloquear" => ["campos" => t('(só o master) usuario_id ou login, bloqueado (1, o padrão: não entra mais, nem pelo token pessoal; 0: desbloqueia); não o próprio'), "exemplo" => t('curl -u lucas:senha -d recurso=usuarios -d acao=bloquear -d login=visitante -d bloqueado=1 http://servidor/relojoeiro/api.php')],
            "transferir" => ["campos" => t('(só o master) usuario_id ou login (o dono de agora), colecao_id, para (o login do novo dono): a coleção passa para o outro, com tudo; a árvore vai junto quando só ela a usa; senão, o novo dono ganha uma cópia da árvore, e a coleção passa para a cópia'), "exemplo" => t('curl -u lucas:senha -d recurso=usuarios -d acao=transferir -d login=lucas -d colecao_id=3 -d para=maria http://servidor/relojoeiro/api.php')],
            "dar_acesso" => ["campos" => t('(só o master) usuario_id ou login; colecao_id (membro de uma coleção) ou dono_id (ou dono, o login: todas as coleções desse dono, também as que vierem)'), "exemplo" => t('curl -u lucas:senha -d recurso=usuarios -d acao=dar_acesso -d login=maria -d dono=lucas http://servidor/relojoeiro/api.php')],
            "excluir" => ["campos" => t('(só o master) login (ou usuario_id), confirmar=1: o usuário sai com tudo o que é dele (as coleções, as árvores, os relógios, os arquivos, os acessos, os tokens); não o próprio; sobra sempre um master'), "exemplo" => t('curl -u lucas:senha -d recurso=usuarios -d acao=excluir -d login=visitante -d confirmar=1 http://servidor/relojoeiro/api.php')],
        ],
        "conta" => [
            "alterar" => ["campos" => t('nivel (o modo da interface: basico, o dia a dia, ou avancado, também as fórmulas, os roteiros, os critérios, as simulações e os totais; o motor é o mesmo), email, idioma (vazio: o da coleção), fuso (o seu fuso horário: um nome que o PHP conheça, como America/Sao_Paulo; navegador: o do aparelho, que as páginas mandam no cookie fuso_navegador (um script manda fuso_pedido=); vazio: o da coleção, senão o do sistema), senha_atual, senha (a nova, com a força da Configuração) e senha_confirmacao (quando vem, igual à nova); só o que vier muda'), "exemplo" => t('curl -u lucas:senha -d recurso=conta -d acao=alterar -d email=lucas@exemplo.com -d idioma=pt-BR -d fuso=America/Sao_Paulo http://servidor/relojoeiro/api.php')],
            "token_criar" => ["campos" => t('nome (onde ele vai ser usado): devolve token, que só aparece agora; ele vale como o seu login (cabeçalho X-Api-Token)'), "exemplo" => t('curl -u lucas:senha -d recurso=conta -d acao=token_criar -d "nome=Atalho do celular" http://servidor/relojoeiro/api.php')],
            "token_revogar" => ["campos" => t('id (um token seu): quem o usava perde o acesso'), "exemplo" => t('curl -u lucas:senha -d recurso=conta -d acao=token_revogar -d id=2 http://servidor/relojoeiro/api.php')],
            "aparelho_lembrar" => ["campos" => t('nome (o aparelho; vazio: o navegador que pediu): o aplicativo no celular. Cria a chave deste aparelho, grava o hash dela e devolve a chave num cookie (aparelho: só HTTP, um ano, na pasta do sistema); daí em diante o pedido que chega com o cookie, sem o login do site, entra como você. Devolve id'), "exemplo" => t('curl -u lucas:senha -c cookies.txt -d recurso=conta -d acao=aparelho_lembrar -d "nome=Celular" http://servidor/relojoeiro/api.php')],
            "aparelho_esquecer" => ["campos" => t('id (um aparelho seu; vazio: o aparelho deste pedido, pelo cookie): a chave deixa de valer, e o cookie deste navegador é apagado se era ele. Trocar a senha esquece todos'), "exemplo" => t('curl -u lucas:senha -d recurso=conta -d acao=aparelho_esquecer -d id=1 http://servidor/relojoeiro/api.php')],
            "push_inscrever" => ["campos" => t('endpoint (https), p256dh e auth (a inscrição do navegador, como o PushManager entrega), aparelho (um nome): o aparelho passa a receber as notificações dos destinos Web Push que apontam para você'), "exemplo" => t('curl -u lucas:senha -d recurso=conta -d acao=push_inscrever --data-urlencode endpoint=https://fcm.googleapis.com/fcm/send/... -d p256dh=BN... -d auth=k3... http://servidor/relojoeiro/api.php')],
            "push_cancelar" => ["campos" => t('id (ou endpoint): o aparelho deixa de receber'), "exemplo" => t('curl -u lucas:senha -d recurso=conta -d acao=push_cancelar -d id=1 http://servidor/relojoeiro/api.php')],
            "push_testar" => ["campos" => t('(nada): manda uma notificação de teste para os seus aparelhos'), "exemplo" => t('curl -u lucas:senha -d recurso=conta -d acao=push_testar http://servidor/relojoeiro/api.php')],
            "smtp_salvar" => ["campos" => t('o seu servidor de e-mail próprio (o Gmail, o Outlook, o do seu provedor): os e-mails que você manda (os destinos de e-mail das suas coleções, os convites, os pedidos de acesso e as respostas a eles, o seu Esqueci a senha e o aviso da sua demonstração) saem por ele; sem ele, pelo servidor do sistema (o config.php). proprio=0: volta ao do sistema (apaga o seu). proprio=1 (o padrão): host (o servidor SMTP, como smtp.gmail.com; quem não é o master só usa servidores da internet, nada da rede do servidor), porta (1 a 65535; vazia: 465 no ssl, 587 no resto), seguranca (tls: STARTTLS, o padrão; ssl; nada), usuario (vazio: sem login), senha (cifrada no banco; vazia: mantém a gravada; nunca volta), remetente (o e-mail de quem a mensagem vem; vazio: o usuario, se for um e-mail, senão o e-mail da conta). A resposta traz smtp (como no recurso=conta)'), "exemplo" => t('curl -u lucas:senha -d recurso=conta -d acao=smtp_salvar -d host=smtp.gmail.com -d porta=587 -d seguranca=tls -d usuario=lucas@gmail.com -d "senha=senha de app" http://servidor/relojoeiro/api.php')],
            "smtp_testar" => ["campos" => t('para (vazio: só a conexão, sem mandar nada): conecta e entra no seu servidor de e-mail próprio e manda um e-mail de teste por ele. A resposta traz teste: metodo, remetente, smtp e envio (cada um null, se não houve, ou {ok, erro}), imap e pop (null: são do sistema), registro (a conversa com o servidor, sem a senha) e config (null). Sem o servidor próprio, é recusado'), "exemplo" => t('curl -u lucas:senha -d recurso=conta -d acao=smtp_testar -d para=lucas@exemplo.com http://servidor/relojoeiro/api.php')],
            "email_testar" => ["campos" => t('(só o master) para (vazio: só as conexões, sem mandar nada): conecta e entra no SMTP, no IMAP (e confere a pasta Enviados) e no POP, os que estiverem configurados, e manda um e-mail de teste para o endereço. A resposta traz teste: metodo, remetente, smtp, imap, pop e envio (cada um null, se não houve, ou {ok, erro}), registro (a conversa com os servidores, linha a linha, sem a senha nem o usuário em base64) e config (o mesmo que o email do recurso=conta). Sem o envio configurado, a resposta é um erro, com teste.config dizendo o que falta'), "exemplo" => t('curl -u lucas:senha -d recurso=conta -d acao=email_testar -d para=lucas@exemplo.com http://servidor/relojoeiro/api.php')],
            "vapid_gerar" => ["campos" => t('(só o master; nada): gera um par de chaves do Web Push; a resposta traz config (as duas linhas para o config.php) e chaves'), "exemplo" => t('curl -u lucas:senha -d recurso=conta -d acao=vapid_gerar http://servidor/relojoeiro/api.php')],
            "excluir" => ["campos" => t('confirmar=1: a sua conta sai com tudo o que é dela (as coleções, as árvores, os relógios, os arquivos, os acessos, os tokens); sobra sempre um master'), "exemplo" => t('curl -u lucas:senha -d recurso=conta -d acao=excluir -d confirmar=1 http://servidor/relojoeiro/api.php')],
        ],
        "colecoes" => [
            "criar" => ["campos" => t('nome, opcao (modelo: com o conjunto inicial, numa árvore nova, o padrão; vazia: numa árvore nova só com a raiz; arvore: numa árvore sua que já existe, com arvore_id: o cadastro fica em comum com as outras coleções dela); o master cria para outro com dono_id. A resposta traz id e arvore_id'), "exemplo" => t('curl -u lucas:senha -d recurso=colecoes -d acao=criar -d "nome=Relógios do meu pai" -d opcao=modelo http://servidor/relojoeiro/api.php')],
            "renomear" => ["campos" => t('id, nome (não repete entre as coleções do dono)'), "exemplo" => t('curl -u lucas:senha -d recurso=colecoes -d acao=renomear -d id=3 -d "nome=Herança" http://servidor/relojoeiro/api.php')],
            "excluir" => ["campos" => t('id, confirmar=1: a coleção sai com tudo o que é dela (os relógios, o histórico, o plano, os destinos, as agendas, os arquivos); a árvore fica'), "exemplo" => t('curl -u lucas:senha -d recurso=colecoes -d acao=excluir -d id=3 -d confirmar=1 http://servidor/relojoeiro/api.php')],
            "arvore_copiar" => ["campos" => t('arvore_id, nome: uma cópia da árvore inteira (os grupos e o cadastro deles), sem coleção; a resposta traz arvore_id'), "exemplo" => t('curl -u lucas:senha -d recurso=colecoes -d acao=arvore_copiar -d arvore_id=1 -d "nome=Grupos para testes" http://servidor/relojoeiro/api.php')],
            "arvore_renomear" => ["campos" => t('arvore_id, nome'), "exemplo" => t('curl -u lucas:senha -d recurso=colecoes -d acao=arvore_renomear -d arvore_id=1 -d "nome=Meus grupos" http://servidor/relojoeiro/api.php')],
            "arvore_excluir" => ["campos" => t('arvore_id, confirmar=1: a árvore sai com o cadastro dela e com as coleções que a usam (e tudo delas)'), "exemplo" => t('curl -u lucas:senha -d recurso=colecoes -d acao=arvore_excluir -d arvore_id=9 -d confirmar=1 http://servidor/relojoeiro/api.php')],
        ],
        "acessos" => [
            "remover" => ["campos" => t('usuario_id; colecao_id (membro de uma coleção sua) ou dono_id (ou dono, o login: o acesso a tudo seu), confirmar=1: a pessoa deixa de ver; nada mais é apagado. Só o dono (ou o master)'), "exemplo" => t('curl -u lucas:senha -d recurso=acessos -d acao=remover -d usuario_id=5 -d colecao_id=1 -d confirmar=1 http://servidor/relojoeiro/api.php')],
            "sair" => ["campos" => t('colecao_id ou dono_id (ou dono), confirmar=1: você deixa de ver (o dono não sai da própria coleção: ele a exclui ou o master a transfere)'), "exemplo" => t('curl -u maria:senha -d recurso=acessos -d acao=sair -d colecao_id=1 -d confirmar=1 http://servidor/relojoeiro/api.php')],
        ],
        "convites" => [
            "convidar" => ["campos" => t('email; colecao_id (uma coleção que você vê) ou dono_id (ou dono: tudo de um dono; só o próprio dono ou o master): o convite do dono (ou do master) sai na hora, por e-mail, com o link (vale CONVITE_DIAS dias; sem e-mail no servidor, a resposta traz link, para você mandar); o de um membro espera o dono aprovar'), "exemplo" => t('curl -u lucas:senha -d recurso=convites -d acao=convidar -d email=amigo@exemplo.com -d colecao_id=1 http://servidor/relojoeiro/api.php')],
            "aprovar" => ["campos" => t('id (um convite de membro, para uma coleção sua): aprova e manda o link'), "exemplo" => t('curl -u lucas:senha -d recurso=convites -d acao=aprovar -d id=4 http://servidor/relojoeiro/api.php')],
            "recusar" => ["campos" => t('id: o convite sai'), "exemplo" => t('curl -u lucas:senha -d recurso=convites -d acao=recusar -d id=4 http://servidor/relojoeiro/api.php')],
            "reenviar" => ["campos" => t('id (um convite já aprovado): manda de novo, com um link novo (o anterior para de valer)'), "exemplo" => t('curl -u lucas:senha -d recurso=convites -d acao=reenviar -d id=4 http://servidor/relojoeiro/api.php')],
            "cancelar" => ["campos" => t('id (quem convidou, ou o dono): o convite sai'), "exemplo" => t('curl -u lucas:senha -d recurso=convites -d acao=cancelar -d id=4 http://servidor/relojoeiro/api.php')],
            "aceitar" => ["campos" => t('token (o do link): quem já tem conta aceita o convite e passa a ver o que ele dá (quem não tem cria a conta pelo link: recurso=cadastro)'), "exemplo" => t('curl -u maria:senha -d recurso=convites -d acao=aceitar -d token=Xy3... http://servidor/relojoeiro/api.php')],
        ],
        "pedidos" => [
            "pedir" => ["campos" => t('colecao_id (o código de uma coleção) ou dono_id (o código de um dono: tudo dele, também o que vier), o código que o dono passou (nunca o login: nada no pedido diz quem tem conta; um código que não serve dá sempre o mesmo erro), mensagem (um recado para o dono): o dono recebe um e-mail; o pedido espera CONVITE_DIAS dias; a resposta e a lista dos seus pedidos mostram só o código até a aprovação'), "exemplo" => t('curl -u maria:senha -d recurso=pedidos -d acao=pedir -d dono_id=1 -d "mensagem=Oi, é a Maria" http://servidor/relojoeiro/api.php')],
            "aprovar" => ["campos" => t('id (o dono do alvo, ou o master): a pessoa passa a ver, e recebe um e-mail'), "exemplo" => t('curl -u lucas:senha -d recurso=pedidos -d acao=aprovar -d id=2 http://servidor/relojoeiro/api.php')],
            "recusar" => ["campos" => t('id: o pedido sai, e a pessoa recebe um e-mail'), "exemplo" => t('curl -u lucas:senha -d recurso=pedidos -d acao=recusar -d id=2 http://servidor/relojoeiro/api.php')],
            "cancelar" => ["campos" => t('id (um pedido seu)'), "exemplo" => t('curl -u maria:senha -d recurso=pedidos -d acao=cancelar -d id=2 http://servidor/relojoeiro/api.php')],
        ],
        "cadastro" => [
            "criar_conta" => ["campos" => t('(sem login) login (até 60 caracteres, sem dois-pontos), senha (com a força da Configuração), senha_confirmacao (quando vem, igual), email, idioma, opcao (modelo: uma coleção com o conjunto inicial; vazia: uma coleção sem nada; pedir: pedir acesso, com colecao_id ou dono_id, o código que o dono passou, e mensagem), convite (o token do link: a conta já vê o que o convite dá; opcao modelo ou nenhuma). Com o cadastro fechado (CADASTRO_ABERTO = false), só com convite. A conta é de demonstração por DEMO_DIAS dias (0: oficial), com aviso por e-mail 7 dias e 1 dia antes; vencida, o cron a apaga com tudo'), "exemplo" => t('curl -d recurso=cadastro -d acao=criar_conta -d login=maria -d senha=segredo123 -d email=maria@exemplo.com -d opcao=modelo http://servidor/relojoeiro/api.php')],
            "esqueci_senha" => ["campos" => t('(sem login) email (ou o login): manda o link para escolher uma senha nova (vale 2 horas); a resposta é a mesma exista a conta ou não'), "exemplo" => t('curl -d recurso=cadastro -d acao=esqueci_senha -d email=maria@exemplo.com http://servidor/relojoeiro/api.php')],
            "conferir_senha" => ["campos" => t('(sem login, sem gravar nada) senha, senha_confirmacao (opcional): a conferência da senha contra a força da Configuração, a que as telas mostram enquanto a pessoa digita. Devolve conferencia: ok (passa em tudo), regras (cada uma: regra, que é tamanho, maiusculas, minusculas, numeros, simbolos ou confirmacao; texto; exigido; tem; ok), forca (0 a 4, pelo tamanho e por quantos tipos de caractere ela mistura) e forca_texto (muito fraca, fraca, razoável, boa, forte)'), "exemplo" => t('curl -d recurso=cadastro -d acao=conferir_senha --data-urlencode "senha=Minha@Senha1" --data-urlencode "senha_confirmacao=Minha@Senha1" http://servidor/relojoeiro/api.php')],
            "nova_senha" => ["campos" => t('(sem login) token (o do link), senha (a nova, com a força da Configuração) e senha_confirmacao (quando vem, igual)'), "exemplo" => t('curl -d recurso=cadastro -d acao=nova_senha -d token=Ab9... -d senha=outra12345 http://servidor/relojoeiro/api.php')],
        ],
        "migracoes" => [
            "aplicar" => ["campos" => t('(nada): aplica as migrações pendentes, na ordem: o SQL de cada uma e, se ela tiver, o passo em PHP'), "exemplo" => t('curl -u lucas:senha -d recurso=migracoes -d acao=aplicar http://servidor/relojoeiro/api.php')],
        ],
        "instalacao" => [
            "instalar" => ["campos" => t('(nada; lingua= escolhe o idioma, como em qualquer pedido: fora do português, o cadastro inicial sai nele e ele vira o idioma padrão, config.idioma): instala o banco do config.php, só num banco vazio (o schema.sql traduzido para o banco, com os passos em PHP das migrações), pelo token (antes da instalação não há usuários); a resposta traz comandos, tabelas e segundos. Depois: o primeiro usuário, em recurso=usuarios, acao=salvar'), "exemplo" => t('curl -H "X-Api-Token: segredo" -d recurso=instalacao -d acao=instalar http://servidor/relojoeiro/api.php')],
        ],
        "importacao" => [
            "importar" => ["campos" => t('banco (o nome do banco antigo, MySQL/MariaDB), substituir (1: apaga antes os relógios e o histórico deste banco; obrigatório quando ele já tem relógios): traz a árvore, os relógios, as fotos, os usuários, os valores dos campos e o histórico, tudo numa transação (parou no meio: nada fica gravado); a resposta traz contagem (quantos de cada)'), "exemplo" => t('curl -u lucas:senha -d recurso=importacao -d acao=importar -d banco=relogios -d substituir=1 http://servidor/relojoeiro/api.php')],
        ],
        "backup" => [
            "fazer" => ["campos" => t('(nada): faz uma cópia agora na BACKUP_PASTA (as mais velhas que passam do BACKUP_MANTER saem); a resposta traz arquivo'), "exemplo" => t('curl -u lucas:senha -d recurso=backup -d acao=fazer http://servidor/relojoeiro/api.php')],
            "restaurar" => ["campos" => t('arquivo (o nome de uma cópia da pasta): antes, guarda uma cópia do que está agora; depois, num passo só, troca todos os registros pelos da cópia (se algo falha, nada muda); só uma cópia da mesma versão do banco; sem o conteúdo dos documentos, eles voltam sem a cópia no banco e o cron refaz a pedida'), "exemplo" => t('curl -u lucas:senha -d recurso=backup -d acao=restaurar -d arquivo=relojoeiro-2026-10-12-200000.jsonl.gz http://servidor/relojoeiro/api.php')],
        ],
    ],
    "senhas" => [
        "como_fica" => t('a senha não fica guardada em lugar nenhum: fica só o hash dela, feito pelo password_hash do PHP com PASSWORD_DEFAULT (bcrypt). O hash tem 60 caracteres: $2y$, o custo com dois dígitos e $ (12 é 2^12 rodadas), o sal (22 caracteres, sorteado a cada senha) e o resultado (31). O sal e o custo vão dentro do próprio hash'),
        "como_confere" => t('o hash não se desfaz em senha (é de mão única). Para conferir, calcula-se o bcrypt da senha digitada com o sal e o custo que estão no hash e compara-se com o resultado: é o que o password_verify do PHP faz no login. A mesma senha dá hashes diferentes a cada cálculo (o sal muda), e todos conferem'),
        "migrar_daqui" => t('leve o login e o senha_hash de cada um (recurso=usuarios, ou a resposta sem recurso) e, no outro sistema, confira a senha digitada contra o hash com o bcrypt dele: cada um entra lá com a mesma senha de sempre. $2y$ (PHP) e $2b$ (Python, Node, Java, C#...) são o mesmo cálculo; se a biblioteca recusar o $2y$, troque o começo por $2b$'),
        "migrar_para_ca" => t('POST recurso=usuarios, acao=salvar, login e senha_hash (um bcrypt $2y$, $2b$ ou $2a$, ou um argon2): o usuário entra aqui com a senha que tinha lá, sem ninguém saber qual é (o $2b$ é guardado como $2y$, o mesmo cálculo)'),
        "php" => t('conferir: password_verify($senha, $hash); fazer: password_hash($senha, PASSWORD_DEFAULT)'),
        "python" => t('pip install bcrypt; conferir: bcrypt.checkpw(senha.encode(), hash.encode()); fazer: bcrypt.hashpw(senha.encode(), bcrypt.gensalt()).decode()'),
        "node" => t('npm install bcryptjs; conferir: require("bcryptjs").compareSync(senha, hash); fazer: require("bcryptjs").hashSync(senha, 12)'),
        "java" => t('Spring Security: new BCryptPasswordEncoder().matches(senha, hash) (com jBCrypt, BCrypt.checkpw(senha, hash) trocando $2y$ por $2a$)'),
        "csharp" => t('BCrypt.Net-Next: BCrypt.Net.BCrypt.Verify(senha, hash)'),
    ],
    "filtros" => [
        "onde" => t('em qualquer consulta: a resposta sem parâmetros e todos os recursos'),
        "incluir" => t('incluir=relogios,plano: só essas partes da resposta'),
        "excluir" => t('excluir=motor,criterios: a resposta sem essas partes'),
        "lista" => t('as regras valem para uma lista da resposta, pelo caminho dela entre os colchetes: relogios, plano, avisos, eventos, usuarios, cron.execucoes, criterios.notas, criterios.conjuntos, agendas_desejadas, relogios.lancamentos, relogios.avisos, relogios.linha_do_tempo, relogio.leituras (na ficha)...; lista dentro de lista vale em cada item'),
        "campo" => t('qualquer campo do item; com ponto entra num objeto (compra.valor) ou, numa lista de itens com identificador, no item daquele identificador (formulas.energia.valor, campos.loja.valor)'),
        "f[lista][campo]=v" => t('igual a v (vários separados por vírgula: igual a um deles; numa lista de valores, se algum for)'),
        "f[lista][campo][de]=v" => t('a partir de v (números como números; datas e textos como texto)'),
        "f[lista][campo][ate]=v" => t('até v (uma data sem hora vai até o fim daquele dia)'),
